	["Adds a buff that deals Physical Damage over time, while increasing Attack Speed and Life Leech. Killing an enemy while this buff is active refreshes the buff duration, and can grant a Frenzy Charge."] = "增加一个持续造成物理伤害的增益效果，同时提高攻击速度和生命偷取效果。击败敌人会刷新该增益效果的持续时间，并提供一个狂怒球。",
