	["After a short preparation time, you fire individual projectiles repeatedly with a Bow or Wand. These projectiles have a small randomised spread. This skill cannot be Triggered."] = "在短暂的准备之后，你使用弓或法杖重复发射单个投射物，这些投射物会稍微随机散射。该技能无法被触发。",
	["After a short preparation time, you fire projectiles repeatedly with a Bow or Wand. These projectiles have a small randomised spread. This skill cannot be Triggered."] = "在短暂的准备之后，你使用弓或法杖重复发射投射物。这些投射物会稍微随机散射。该技能无法被触发。",
	["After selecting a row You can also shift+click on another row to select a range of rows to search."] = "选中一行后，可按住 Shift 点击另一行，选择连续多行进行搜索。",
