	["All Sockets"] = "全部插槽",
	["All Types"] = "所有类型",
	["All are invited to his feast, one way or another."] = "所有人都将参加盛宴，无论哪种途径。",
	["All bonuses from an Equipped Shield apply to your Minions instead of you"] = "盾牌上的所有属性会套用于你的召唤生物，而非角色本身",
	["All gems default to level 1."] = "所有宝石的默认等级为 1。",
	["All gems default to their highest valid corrupted gem level."] = "所有宝石默认使用腐化可达到的最高等级。",
	["All gems default to their highest valid non-corrupted gem level that your character meets the level requirement for.\nThis hides gems with a minimum level requirement above your character level, preventing them from showing up in the dropdown list."] = "所有宝石默认使用角色等级允许的最高未腐化等级。\n最低等级需求高于角色等级的宝石将从下拉列表中隐藏。",
	["All gems default to their highest valid non-corrupted gem level."] = "所有宝石默认使用未经腐化可达到的最高等级。",
	["All hits are Critical Strikes"] = "所有击中都造成暴击",
	["All other Summoned Totems die when you Summon a Totem"] = "当你召唤图腾时，其他所有已召唤图腾死亡",
	["All skills:"] = "所有技能：",
	["Allflame Infused Coral"] = "染火珊瑚",
	["Allies on your Brine Ground gain 10% of Physical Damage as extra Cold Damage and as extra Lightning Damage"] = "海蚀地面上的友军获得等同于物理伤害 10% 的额外冰霜伤害和额外闪电伤害",
	["Allies on your Fungal Ground gain +25% Chaos Resistance."] = "真菌地表上的友军获得 +25% 混沌抗性。",
	["Allocating"] = "分配天赋",
	["Allocating this node and all nodes leading to it will give you:"] = "点出此天赋及通往它的全部天赋后的属性变化：",
	["Allocating this node will give you:"] = "点出此天赋后的属性变化：",
	["Allows you to manually set the Stack Potential value for a skill."] = "允许手动设置技能的叠层潜力。",
	["Allows you to manually set the Stack Potential value for a skill.\nStack Potential equates to the number of times you are able to inflict a Bleed on an enemy before the duration of your first Bleed expires"] = "允许手动设置技能的叠层潜力。\n叠层潜力指在第一层流血结束前，能够对敌人施加流血的次数",
	["Allows you to manually set the Stack Potential value for a skill.\nStack Potential equates to the number of times you are able to inflict an Ignite on an enemy before the duration of your first Ignite expires"] = "允许手动设置技能的叠层潜力。\n叠层潜力指在第一次点燃结束前，能够对敌人施加点燃的次数",
	["Also affects areas in front of and behind the targeted area"] = "同样影响目标地点前后区域",
	["Alternates triggering Flames of Judgement and Storm of Judgement"] = "交替触发审判烈焰和审判风暴",
	["Alva's Gift"] = "阿尔瓦的赠礼",
	["Always Angry"] = "怒意难平",
	["Always Crit Aura"] = "必定暴击光环",
	["Always Freezes enemies"] = "对敌人始终造成冻结状态",
	["Amanamu (The Loyal Few)"] = "阿曼娜姆（忠信之众）",
	["Ambidexterity"] = "卓越",
	["Ambush"] = "伏击",
	["Amethyst Flask"] = "紫晶药剂",
	["Amount of Hallowing Flame stacks applied to the enemy."] = "施加于敌人的圣焰层数。",
	["Amount of Hallowing Flame stacks removed from enemies by allies recently."] = "近期内友军从敌人身上移除的圣焰层数。",
	["Amount of Rage Sacrificed (if not maximum)"] = "献祭的怒火量（未达到上限时）",
	["Amount of stacks of Barnacle applied to the enemy."] = "施加于敌人的藤壶层数。",
	["Amount of stacks of Barnacle applied to the enemy.\n\n(Enemies affected by Barnacles Convert 5% of Physical Damage to Cold and have 5% increased duration of Chill and Freeze on them.\nEach instance of Barnacles lasts 30 seconds and can be inflicted up to 10 times)"] = "施加于敌人的藤壶层数。\n\n（受到藤壶影响的敌人将物理伤害的 5% 转化为冰霜伤害，其受到的冰缓和冻结持续时间提高 5%。\n每层藤壶持续 30 秒，最多可施加 10 层）",
	["Amount of stacks of Hoarfrost applied to the enemy."] = "施加于敌人的白霜层数。",
	["Amount of stacks of Scorch applied to the enemy."] = "施加于敌人的烧灼层数。",
	["Amount of stacks of Shock applied to the enemy."] = "施加于敌人的感电层数。",
	["Amplify"] = "增幅",
	["Amulet"] = "项链",
	["An Enemy Writhing Worm spawns every 2 seconds"] = "每 2 秒生成一只敌方蠕虫",
	["An arc of lightning reaches from the caster to a targeted enemy and chains to other enemies, but not immediately back. Each time the arc chains, it will also chain a secondary arc to another enemy that the main arc has not already hit, which cannot chain further."] = "一道电弧从施放者射向目标，并会弹射至其他敌人，但不会立刻向原目标弹射。每次主电弧弹射时，也会向另一个主电弧尚未击中的敌人发射次电弧，次电弧不能再连锁弹射。",
	["An arc of lightning reaches from the caster to a targeted enemy and chains to other enemies. Each time the arc chains, it will also chain a secondary arc to another enemy, but this secondary arc cannot chain further."] = "一道电弧从施放者射向目标，并会弹射至其他敌人。每次主电弧弹射时，也会向另一个敌人发射次电弧，次电弧不能再连锁弹射。",
	["An arc of lightning reaches from the caster to a targeted enemy and splits to simultaneously hit several other enemies."] = "一道电弧从施放者射向目标并分裂，同时击中附近的多个敌人。",
	["An arcane pattern, secrets bound. Blind truth splinters with lies abound."] = "一种秘法的图案，其中隐藏着秘密。盲目的真理中散落着许多谎言。",
	["An expanding wave of energy surges forward, damaging enemies in a cone-shaped area over a duration. Each enemy hit is inflicted with Exposure matching the element of which they took the highest damage. Only one Wave of Conviction can be active at a time"] = "一股逐渐拓展的能量波向前涌动，在一段时间内对锥形范围内的敌人造成伤害。被击中的每个敌人会根据受到的最高伤害的类型，遭受一个该元素的曝露负面效果。一次只能激活一个定罪波。",
	["An expanding wave of energy surges outwards from you, damaging enemies in a ring-shaped area over a duration. The ring then returns, damaging enemies again on the way back. Only one Wave of Conviction can be active at a time"] = "一股逐渐拓展的能量波从你身上向外涌动，在一段时间内对环形区域内的敌人造成伤害。随后环形在返回途中再次对敌人造成伤害。一次只能激活一个定罪波。",
	["An icy blast explodes around the caster, dealing cold damage to enemies, and leaving behind a whirling vortex which deals cold damage over time and chills enemies caught in it."] = "一个会在施法者周围爆炸的冰爆，对敌人造成冰霜伤害，并留下一个漩涡，对于在其中的敌人继续造成持续冰霜伤害和冰缓。",
	["An icy blast explodes around the caster, dealing cold damage to enemies, and leaving behind a whirling vortex which deals cold damage over time and chills enemies caught in it. If the caster targets near their Frostbolt projectiles, it will explode from a number of those projectiles instead, destroying them."] = "一个会在施法者周围爆炸的冰爆，对敌人造成冰霜伤害，并留下一个漩涡，对于在其中的敌人继续造成持续冰霜伤害和冰缓。若施法目标区域附近存在着寒冰弹，冰爆则会出现在寒冰弹的位置。",
	["An icy projectile which has a chance to freeze enemies it passes through. The projectile fades quickly, reducing damage and freezing chance until it dissipates."] = "发出一个半月形的寒冰投射物, 被击中的敌人将有几率被冰冻. 这个投射物很快就会消散, 而其伤害与冻结几率将会随着飞行时间递减.",
	["Ancestral Bond"] = "先祖魂约",
	["Ancestral Boost does not apply to repeats of the Attack"] = "先祖加持对重复的攻击无效",
	["Ancestral Call"] = "先祖召唤(辅)",
	["Ancestral Call Support"] = "先祖召唤(辅)",
