	["AoE, Attack, Physical, Duration, Fire"] = "效果区域, 攻击, 物理, 持续时间, 火焰",
	["AoE, Attack, Physical, Duration, Fire, Orb"] = "效果区域, 攻击, 物理, 持续时间, 火焰, 法球",
	["AoE, Channelling, Attack, Melee, Lightning"] = "效果区域, 持续吟唱, 攻击, 近战, 闪电",
