	["Append"] = "追加",
	["Applies a buff boosting chance to shock. When you shock an enemy while you have this buff, creates a spherical field of energy attached to the shocked enemy for a duration, which will damage it and other nearby enemies with beams of lightning."] = "施加增益效果，提高感电几率。在拥有此增益效果的情况下使敌人感电时，会在感电的敌人身上产生一个球形能量场，并使敌人持续感电一段时间，其闪电束会对该敌人和附近的其他敌人造成伤害。",
	["Applies a buff boosting chance to shock. When you shock an enemy while you have this buff, creates a spherical field of energy attached to the shocked enemy for a duration, which will damage it and other nearby enemies with beams of lightning. The strength of the field depends on the magnitude of shock affecting the enemy when it is created."] = "施加增益效果，提高感电几率。在拥有此增益效果的情况下使敌人感电时，会在感电的敌人身上产生一个球形能量场，并使敌人持续感电一段时间，其闪电束会对该敌人和附近的其他敌人造成伤害。能量场的强度取决于形成能量场时对敌人造成影响的感电程度。",
	["Applies a buff that adds to your armour, and can take some of the damage from hits for you before being depleted. When the buff expires or is depleted, the skill deals reflected damage to enemies around you based on the total damage that was taken from the buff. Shares a cooldown with other Guard skills."] = "施加一个增益效果，增加护甲值，并在耗尽前替你承担部分伤害。当该增益效果时间结束或耗尽时，该技能将基于该增益效果承受的总伤害，把伤害反射给周围的敌人。与其它防卫技能共用冷却时间。",
	["Applies a buff that protects the lower half of your life, preventing some of the immediate life loss when damaged by hits and applying the loss over time instead. Your life cannot be raised above low life other than by flasks, and while above low life, skills will cost life as well as mana."] = "施加一个增益效果，在你生命低于一半时提供保护，防止被击中时立刻失去生命，改为随时间缓慢失去生命值。在该增益效果下，你无法通过除药剂外的手段将生命恢复至高于低血状态，并且一旦生命高于低血状态，施放技能时会同时消耗生命和魔力。",
	["Applies a buff that raises your armour, and takes some of the damage from hits for you before being depleted. Each second, the skill deals reflected damage to surrounding enemies based on the damage taken by the buff in that second. When the buff is removed, the skill deals reflected damage to enemies around you based on the total damage that was taken by the buff. You cannot have the buff at the same time as any other Guard skill."] = "施加一个增益效果，提升护甲值，并在耗尽前替你承担部分伤害。该技能每秒都会向周围敌人反射伤害，其数值由反射时那一秒受到的伤害来决定。增益效果结束时，该技能会基于增益效果累计受到的总伤害对你周围的敌人反射伤害。你在具有其它防卫技能时不能获得该增益效果。",
	["Applies a buff to you and each of your minions, which will take some of the damage from enemy hits before being depleted. The buff also grants immunity to bleeding. Shares a cooldown with other Guard skills."] = "给你和你的每个召唤生物施加一个增益效果，在其耗尽之前替你承受部分敌人的击中伤害。该增益效果还免疫流血。和其它防卫技能共用冷却时间。",
	["Applies a buff which can take some of the damage from hits for you before being depleted. Shares a cooldown with other Guard skills."] = "施加一个增益效果，在其耗尽之前替你承受部分伤害。和其它防卫技能共用冷却时间。",
	["Applies a debuff to Enemies, removing some of their resistance to Chaos damage."] = "对敌人施加一个减益, 移除他们部分混沌抗性.",
	["Applies a debuff to a specific enemy which signals your minions to consider that enemy to be the Prey. All minions from skills supported by any Predator Support will target that enemy. Only one enemy can be the Prey at a time. This skill cannot be used by Totems, Traps, or Mines."] = "给一个指定的敌人施加减益效果，使你的召唤生物把它当作掠食目标。所有由【掠食】辅助的技能产生的召唤生物都会以它为目标。你一次只能有一个【掠食信标】。该技能不能用于图腾、陷阱和地雷。",
	["Applies a debuff to enemies in a small area, which deals chaos damage over Time. Linked hex curses are also applied to those enemies. The debuff deals more damage and lasts longer for each hex applied this way.  This skill cannot be used by Totems, Traps, or Mines."] = "对一小片区域里的敌人施加减益效果，造成持续混沌伤害，并把连接的魔蛊技能施加给它们。通过这种方式每施加一种魔蛊，就能使该减益效果的伤害更高，持续越久。该技能不能用于图腾、陷阱和地雷。",
	["Applies a debuff to enemies in an area, which deals chaos damage over Time. Linked hex curses are also applied to those enemies. The debuff deals more damage and lasts longer for each hex applied this way.  This skill cannot be used by Totems, Traps, or Mines."] = "对一片区域里的敌人施加减益效果，造成持续混沌伤害，并把连接的魔蛊技能施加给它们。通过这种方式每施加一种魔蛊，就能使该减益效果的伤害更高，持续越久。该技能不能用于图腾、陷阱和地雷。",
	["Applies mods that use `while stationary` and `per / every second while stationary`"] = "应用静止时及静止时每秒生效的词缀。",
	["Apply Eldritch Implicits from current gear when comparing new gear, given the new item doesn't have any influence"] = "比较新装备时，若新物品没有任何势力，沿用当前装备的异能固定词缀。",
	["Apply a debuff to enemies in front of you which deals chaos damage over time. Enemies who aren't already debuffed by Blight are also hindered for a longer secondary duration, slowing their movement and reducing their life regeneration rate. Continued channelling adds layers of damage to the debuff, each with their own duration."] = "对前方锥形范围内的敌人造成减益效果，持续造成混沌伤害。尚未被枯萎影响的敌人也会受到较长时间的间接阻碍，降低他们的移动速度和生命再生速度。持续吟唱叠加的伤害减益效果有独自的持续时间。",
	["Apply a debuff to enemies in front of you which deals chaos damage over time. Enemies who aren't already debuffed by Blight are also hindered for a shorter secondary duration, slowing their movement. Continued channelling adds layers of damage to the debuff, each with their own duration."] = "持续吟唱该技能会对前方锥形范围内的敌人造成一个可叠加的减益效果和持续混沌伤害. 当敌人刚被法术命中时会被短暂的减速. 每层可叠加的减益和伤害都有独自的持续时间.",
	["Apply a debuff to enemies in front of you which deals chaos damage over time. Enemies who aren't already debuffed by Blight are also hindered for a shorter secondary duration, slowing their movement. Continued channelling adds layers of damage to the debuff, each with their own duration. The damaging debuff is spread by Contagion."] = "对前方的敌人造成减益效果，持续造成混沌伤害。当敌人刚被法术命中时会受到短暂的缓速，降低移动速度。持续吟唱叠加的伤害减益效果有独自的持续时间。伤害减益效果可由【瘟疫】传染。",
	["Apply a powerful debuff to enemies around you which deals chaos damage over time. Then applies two additional layers in a larger area, growing greatly in size each time. Enemies are also substantially hindered for a shorter secondary duration, slowing their movement."] = "对你周围的敌人施加一个强力的减益效果，持续对其造成混沌伤害。随后在一片较大的区域内施加额外两层，每一次施加都会大幅扩大面积。被主要作用区域影响的敌人还会遭受短时间的减速效果。",
