	["Attack enemies with a forceful melee strike that also hurts you. Successive uses will raise the damage dealt both to enemies and you. Stunning an enemy with the strike releases a damaging pulse. Requires a Mace, Sceptre, Axe or Staff."] = "朝敌人发出猛烈一击，同时伤害自身。连续施放会同时提高对敌我双方的伤害。用它眩晕敌人可以施放一道伤害性脉冲。需要用锤类、短杖、斧类和长杖施放。",
	["Attack enemies with a forceful melee strike. Stunning an enemy with the strike releases a damaging pulse. Requires a Mace, Sceptre, Axe or Staff."] = "朝敌人发出猛烈一击，用它眩晕敌人可以施放一道伤害性脉冲。需要用锤类、短杖、斧类和长杖施放。",
	["Attack enemies with greatly increased range, creating a chilling area that deals cold damage over time if it hits. Requires a Melee Weapon."] = "大幅增加攻击范围，击中时产生一片冰缓区域，持续造成冰霜伤害。限定近战武器。",
	["Attack enemies with increased range, releasing icy blades from the first enemy hit which fly at other enemies. Requires a Melee Weapon."] = "增加攻击范围。当被第一个被击飞的敌人与其他敌人碰撞时释放冰霜之刃。限定近战武器。",
	["Attack time"] = "攻击耗时",
	["Attack with a melee weapon, gaining a Gathering Lightning buff for a duration if you hit an enemy. While you have Gathering Lightning, attacks with this skill will cause chaining beams of lightning, which chain additional times the more Gathering Lightning you have."] = "使用近战武器攻击，击中敌人则在一段时间内获得一层聚雷增益效果。拥有聚雷效果时，该技能的攻击会引发连锁闪电光束，聚雷层数越高，连锁次数越多。",
	["Attack with a melee weapon, gaining static energy for a duration if you hit an enemy. While you have static energy, you'll frequently hit a number of nearby enemies with beams, dealing attack damage."] = "使用近战武器攻击，击中敌人则在一段时间内获得静电场。它会用光束频繁地击中周围一定数量的敌人，造成攻击伤害。",
