	["Attacks Exerted by this Skill cannot be Exerted by other Skills"] = "被该技能增助的攻击不能被其它技能增助",
	["Attacks an area in front of you. Each Reave that hits an enemy grants stages, which you will begin to lose after a short period without hitting anything. Only works with Daggers, Claws, and One-Handed Swords."] = "攻击前方一片区域。击中敌人的每道冲击波都会积累阶段，只要短期内没有击中任何目标就会失去阶段。限定匕首，爪类，单手剑。",
	["Attacks enemies with a forceful blow. Requires a Mace, Sceptre, Axe, Sword or Staff."] = "对敌人进行一次强力攻击。限定锤类、短杖、斧类，剑类或长杖。",
	["Attacks enemies with a forceful blow. Requires a Staff."] = "对敌人进行一次强力攻击。需要长杖发动。",
	["Attacks enemies with a melee strike, applying a debuff for a short duration. If a non-unique enemy dies while affected by the debuff, the enemy's corpse will be consumed and a Sentinel of Dominance with the same rarity, prefix and suffix modifiers will be summoned for a longer secondary duration."] = "近战攻击敌人，在短期内施加一个减益效果。如果非传奇敌人在受到该效果影响时击败，则会消耗它的灵柩创造一个统御哨兵，具有相同稀有度、前缀和后缀，并持续一段更长的时间。",
	["Attacks enemies with a powerful melee strike which grants Fortification, reducing damage you take from hits. The cooldown can be bypassed by expending an Endurance Charge. Requires a Melee Weapon."] = "使用一次强力的近战攻击打击敌人并获得防御效果，降低你受到的伤害。可以通过消耗一个耐力球来跳过冷却时间。需要近战武器。",
	["Attacks fire an additional Projectile"] = "攻击额外发射一个投射物",
	["Attacks have 10% chance to Ignite"] = "火焰伤害击中时有 10% 的几率点燃敌人",
	["Attacks have 10% chance to Maim on Hit"] = "攻击击中时有 10% 的几率造成瘫痪",
	["Attacks have 10% chance to cause Bleeding"] = "攻击有 10% 的几率导致流血",
	["Attacks have 100% Arcane Might while wielding a Wand"] = "持握法杖时，攻击带有 100% 奥术之力",
	["Attacks have 15% chance to Ignite"] = "火焰伤害击中时有 15% 的几率点燃敌人",
	["Attacks have 15% chance to cause Bleeding"] = "攻击有 15% 的几率导致流血",
	["Attacks per second"] = "每秒攻击次数",
	["Attacks used by Totems have 10% increased Attack Speed"] = "图腾所使用攻击的攻击速度加快 10%",
	["Attacks used by Totems have 5% increased Attack Speed"] = "图腾所使用攻击的攻击速度加快 5%",
	["Attacks used by Totems have 6% increased Attack Speed"] = "图腾所使用攻击的攻击速度加快 6%",
	["Attacks used by Totems have 8% increased Attack Speed"] = "图腾所使用攻击的攻击速度加快 8%",
	["Attacks with Melee Weapons deal 12% increased Damage with Ailments"] = "近战武器攻击造成的异常状态伤害提高 12%",
	["Attacks with Melee Weapons deal 4% increased Damage with Ailments"] = "近战武器攻击造成的异常状态伤害提高 4%",
	["Attacks with One Handed Melee Weapons deal 16% increased Damage with Ailments"] = "单手近战武器攻击造成的异常状态伤害提高 16%",
	["Attacks with One Handed Melee Weapons deal 25% increased Damage with Ailments"] = "单手近战武器攻击造成的异常状态伤害提高 25%",
	["Attacks with One Handed Weapons deal 20% increased Damage with Ailments"] = "单手武器攻击造成的异常状态伤害提高 20%",
	["Attacks with One Handed Weapons deal 30% increased Damage with Ailments"] = "单手武器攻击造成的异常状态伤害提高 30%",
	["Attacks with Supported Skills count as Exerted"] = "被辅助技能的攻击视为被增助",
	["Attacks with Two Handed Melee Weapons deal 10% increased Damage with Ailments"] = "双手近战武器攻击造成的异常状态伤害提高 10%",
	["Attacks with Two Handed Melee Weapons deal 12% increased Damage with Ailments"] = "双手近战武器攻击造成的异常状态伤害提高 12%",
	["Attacks with Two Handed Melee Weapons deal 14% increased Damage with Ailments"] = "双手近战武器攻击造成的异常状态伤害提高 14%",
	["Attacks with Two Handed Melee Weapons deal 16% increased Damage with Ailments"] = "双手近战武器攻击造成的异常状态伤害提高 16%",
	["Attacks with Two Handed Melee Weapons deal 20% increased Damage with Hits and Ailments"] = "双手近战武器攻击造成的击中和异常状态伤害提高 20%",
	["Attacks with Two Handed Melee Weapons deal 25% increased Damage with Ailments"] = "双手近战武器攻击造成的异常状态伤害提高 25%",
	["Attacks with Two Handed Melee Weapons deal 25% increased Damage with Hits and Ailments"] = "双手近战武器攻击造成的击中和异常状态伤害提高 25%",
	["Attacks with Two Handed Melee Weapons deal 30% increased Damage with Ailments"] = "双手近战武器攻击造成的异常状态伤害提高 30%",
	["Attacks with Two Handed Weapons deal 25% increased Damage with Hits and Ailments"] = "双手武器攻击造成的击中和异常状态伤害提高 25%",
	["Attacks with Two Handed Weapons deal 60% increased Damage with Hits and Ailments"] = "双手武器攻击造成的击中和异常状态伤害提高 60%",
	["Attacks with both weapons, dealing the damage of both in one strike. Dual wield only. Does not work with wands."] = "使用两把武器对目标同时进行攻击并造成伤害. 限定双持（不包含法杖）.",
	["Attacks with both weapons, dealing the damage of both in one strike. Requires dual-wielding two different melee weapon types to use."] = "使用两把武器对目标同时进行攻击并造成伤害。限定双持两种不同类型的近战武器。",
	["Attacks with your weapon, applying a charged debuff to enemies hit by your strike, and an uncharged debuff to any other enemies hit. Upon reaching 6 charges, expiring, or the enemy's death, the charged debuff is removed to damage that and other surrounding enemies. Enemies with either debuff explode when they die, damaging other surrounding enemies. Damage from this explosion cannot be reflected. Requires a Sword, Axe, Mace, Sceptre, Staff or Unarmed."] = "用武器攻击敌人，施加一个有层数的主减益效果，并对击中的其它敌人附加一个不带层数的次要减益效果。主减益效果叠满 6 层、自然消减或带有该效果的敌人被击败时被消除，对该敌人及周围其它敌人造成伤害。其它带有次要减益效果的敌人被击败时也会爆炸，对周围敌人造成伤害。爆炸造成的伤害无法被反射。限定剑类、斧类、锤类、短杖、长杖或是空手。",
	["Attacks with your weapon, applying a charged debuff to you the first time you hit an enemy with this skill. Upon reaching 6 charges, or charges expiring, the charged debuff is removed to damage nearby enemies. Requires a Sword, Axe, Mace, Sceptre, Staff or Unarmed."] = "用武器攻击敌人，该技能初次击中敌人时施加一个有层数的减益效果。减益效果叠满 6 层或自然消减时被消除，对周围敌人造成伤害。限定剑类、斧类、锤类、短杖、长杖或是空手。",
	["Attacks with your weapon, inflicting a debuff on enemies hit by the strike. If a debuffed enemy dies while poisoned, Pestilent Strike inflicts a secondary chaos damage over time debuff on enemies around them, based on the poisons on the slain enemy. This damage is not affected by your damage modifiers. Requires a Claw or Dagger."] = "用武器发动攻击，击中给敌人施加一个减益效果。一旦具有该减益效果的敌人中毒而败，致疫打击就会给它周围的敌人施加第二重减益效果，基于被击败的敌人身上的中毒造成混沌持续伤害。该伤害不受伤害词缀影响。限定爪类和匕首。",
