	["Auras from your Skills can only affect you\nAura Skills have 1% more Aura Effect per 2% of maximum Mana they Reserve\n40% more Mana Reservation of Aura Skills"] = "你技能的光环只能影响你\n光环技能的光环效果按照它们每保留 2% 魔力上限就总增 1%\n光环技能的魔力保留总增 40%",
	["Auras from your Skills grant 2% increased Attack and Cast\nSpeed to you and Allies"] = "你技能的光环可使你和周围友军的攻击和施法\n速度加快 2%",
	["Auras from your Skills grant 3% increased Attack and Cast\nSpeed to you and Allies"] = "你技能的光环可使你和周围友军的攻击和施法\n速度加快 3%",
