	["Average: Averages out Warcry usage with cast time, attack speed and warcry cooldown."] = "平均：根据施放时间、攻击速度和战吼冷却时间计算战吼使用的平均效果。",
	["Average: Averages the effect based on Pact uptime."] = "平均：根据契约生效时间占比计算平均效果。",
	["Average: Damage Reduction from Defending with Double Armour is proportional to chance"] = "平均：以两倍护甲防御获得的伤害减免按触发几率折算",
	["Average: Modifiers will grant one third of their value to Fire, Cold, and Lightning simultaneously"] = "平均：词缀数值同时按三分之一计入火焰、冰霜和闪电",
	["Average: damage is based on the average application"] = "平均：按平均生效效果计算伤害",
	["Average: damage is based on the average application, including both crits and non-crits"] = "平均：按包含暴击及非暴击的平均效果计算伤害",
	["Average: includes burst regen, averaged based on uptime"] = "平均：计入爆发再生，并按生效时间占比折算",
	["Average: includes chance gains, averaged based on uptime"] = "平均：计入几率触发的获取效果，并按生效时间占比折算",
	["Average: uses the Average of all typed damage types (except Damage Over Time and Untyped)"] = "平均：使用所有明确类型伤害的平均值（持续伤害及无类型伤害除外）",
