	["Category"] = "类别",
	["Cause spires of bone to erupt from the earth around you. When you use a slam on them, these spires will explode to deal damage in an area and inflicting bleeding."] = "使你周围的地面爆发出白骨尖刺。当你使用猛击击打它们时，这些尖刺会爆炸，对周围区域造成伤害，并施加流血。",
	["Causes Bleeding"] = "导致流血",
	["Causes Damage with Arc Hits to be rolled twice, and the maximum roll used."] = "电弧击中伤害取值两次，并采用较高值。",
	["Causes one of your existing Sentinels of Absolution to Ascend, becoming more powerful, gaining new spells, and overriding its duration, while maintaining its other bonuses, including from support gems. If you cannot have more Ascended Sentinels of Absolution, an existing one will be refreshed instead."] = "使你已有的一个赦罪哨卫将获得飞升，使其变得更加强大并获得新的法术，同时覆盖该哨兵的持续时间，并保留它的相关加成（包括来自宝石的加成）。如果你已经无法拥有更多飞升的赦罪哨卫，那么已有的飞升哨卫将会被刷新。",
