	["Changes which protocol is used when downloading updates and importing builds."] = "更改下载更新和导入构筑时使用的网络协议。",
	["Channel Time"] = "持续吟唱时间",
	["Channel this skill to move towards a targeted location while spinning constantly attacking enemies in an area around you. While channelling this skill, you cannot be knocked back."] = "持续吟唱该技能，向指定地点旋转移动，持续攻击你周围的敌人。持续吟唱该技能时，你无法被击退。",
	["Channel this skill to reserve more and more of your life, building up power in a marker on the ground under you. Release to deal physical damage in an area based on how much life you reserved. Cannot be cast by Totems."] = "吟唱该技能会不断保留生命，为你身下的印记灌注力量。施放印记会根据保留的生命量造成物理伤害。不能被图腾施放。",
	["Channel time"] = "持续吟唱耗时",
	["Channel to charge up your bow, gaining stages. Release to trigger one supported bow skill for each stage gained. If there are no supported skills, but at least one stage was gained, this skill will fire its own arrow instead. Cannot be used by Totems."] = "持续吟唱给弓箭充能，积累层数。释放时，每层都会触发一种被辅助的弓类技能。若没有任何被辅助的技能，又至少积累了一层效果，则该技能会发射它原本的箭矢。无法用于图腾。",
	["Channel to conjure an orb above you, which pelts nearby enemies with projectiles that impact the ground and explode. Channelling for longer builds up stages on the skill. When you stop channelling, the stages decay over a duration."] = "吟唱后在你上方生成一个光球，向周围敌人发射投射物，接触地面后会爆炸。吟唱时间越长，技能等阶越高。停止吟唱后，等阶会持续消退。",
	["Channel to create an expanding circle area around you that blinds enemies within it. When you stop channelling, deals damage in a smaller area around each enemy in the circle. Requires a Dagger, Claw or One-Handed Sword."] = "在周身引导并创造一个不断拓展的圆环区域，身处其中的敌人将被致盲。当你停止引导时，对圆环较小区域内的所有敌人造成伤害。限定匕首、爪类、或单手剑。",
	["Channel to improve runes placed by Stormbind based on the mana you spend channelling this skill. Release to detonate the targeted rune, which will cause other runes to detonate in a chain reaction."] = "持续吟唱，根据你吟唱该技能消耗的魔力来强化【缚雷之纹】放置的符纹。释放会引爆目标地点的符纹，并同时连锁引爆其它符纹。",
	["Channel to improve runes placed by Stormbind based on the mana you spend channelling this skill. Release to detonate the targeted rune, which will cause other runes to detonate in a chain reaction. Detonation can teleport you to the targeted Rune."] = "持续吟唱，根据你吟唱该技能消耗的魔力来强化【缚雷之纹】放置的符纹。释放会引爆目标地点的符纹，并同时连锁引爆其它符纹。引爆可将你传送到目标符纹处。",
	["Channel to infuse an arrow with chaos, gaining stages while it is held. Release to fire it, leaving spore pods in its wake. Each spore pod blooms, firing thorn arrows, which travel for a short time before dissipating. Modifiers that cause additional projectiles to be fired will only apply to the initial arrows, and the spore pods will be divided between those arrows."] = "通过吟唱给一支箭矢灌注混沌能量，可以蓄力积累阶数。将其发射后，飞行轨迹上会投下孢囊。每个孢囊都会绽放，喷射荆棘之箭，飞行一小段时间后消失。产生额外投射物的词缀只可以影响最初的箭矢数量，产生的孢囊会由箭矢均分。",
	["Channel to project an illusion which you steer. You gain stages while it moves, until it stops at a maximum total distance. Waves of area damage frequently pulse along its path, based on your attack speed. Stop channelling to release the illusion, dealing a final wave of damage. Requires a Melee Weapon."] = "持续吟唱以向你朝向的方向投射一个幻象。幻象移动时你获得层数，直至其移动到最大距离为止。幻象行进的路径上会根据你的攻击速度来频繁爆发范围伤害。停止吟唱以释放该幻象，造成最后一波伤害。需要近战武器。",
	["Channel to project an illusion which you steer. You gain stages while it moves, until it stops at a maximum total distance. Waves of area damage frequently pulse along its path, based on your attack speed. Stop channelling to teleport to the illusion, dealing a final wave of damage. Requires a Melee Weapon."] = "向你朝向的方向吟唱并发射一个幻象。幻象移动时你获得层数，直至其移动到最大距离为止。幻象行进的路径上会根据你的攻击速度来频繁爆发范围伤害。停止吟唱后可将自己传送至幻象处，并以一波伤害作为技能收尾。需要近战武器。",
	["Channel to spread runes on the ground in a growing pattern. The runes fade away after a duration, or will be immediately removed and deal damage in a circular area when detonated by Rune Blast. Enemies standing on the runes are Hindered, reducing their movement speed."] = "持续吟唱，在地上不断扩大的结界中扩散符纹。符纹持续一段时间后消失，或者被【爆裂符纹】引爆，立刻朝四面八方造成伤害。站立在符纹上的敌人会被【缓速】，并降低移动速度。",
	["Channeling for # seconds"] = "引导持续秒数",
	["Channelling Damage"] = "引导伤害",
	["Channelling Skill Damage"] = "吟唱技能伤害",
	["Channelling Skill Damage Mastery"] = "吟唱技能伤害专精",
	["Channelling Skills deal 12% increased Damage"] = "持续吟唱技能伤害提高 12%",
	["Channelling Skills deal 20% increased Damage"] = "持续吟唱技能伤害提高 20%",
	["Channelling Skills deal 25% increased Damage"] = "持续吟唱技能伤害提高 25%",
	["Channelling Skills deal 30% increased Damage"] = "持续吟唱技能伤害提高 30%",
	["Channelling Skills have 8% increased Attack and Cast Speed"] = "持续吟唱技能的攻击和施法速度加快 8%",
	["Channelling Spells deal 5% more Damage and"] = "引导法术的伤害总增 5%，且",
	["Channelling Spells have 10% more Cost"] = "引导法术的消耗总增 10%",
	["Channelling draws in energy around you to repeatedly build up stages, damaging a number of nearby enemies when you do so. Release to unleash this energy in a burst around you and a beam in front of you. Modifiers to area of effect do not affect the beam. Maximum of 10 Stages."] = "持续吟唱时会在你的周围汇聚能量，不断堆叠，对周围的一群敌人造成伤害。释放此技能会在你周围产生一次冲击，并在面前射出一道光束。效果范围词缀不影响该光束。最多叠加 10 层。",
	["Channelling draws in energy around you to repeatedly build up stages, damaging a number of nearby enemies when you do so. Release to unleash this energy in a powerful burst around you. Maximum of 10 Stages."] = "持续吟唱时会在你的周围汇聚能量，不断堆叠，对周围的一群敌人造成伤害。释放此技能会在你周围产生一次强大的冲击。最多叠加 10 层。",
	["Channelling draws in energy around you to repeatedly build up stages. Release to unleash this energy in a beam in front of you. Modifiers to area of effect do not affect this skill. Maximum of 10 Stages."] = "持续吟唱时会在你的周围汇聚能量，不断堆叠。释放此技能会在你面前射出一道光束。效果范围词缀不影响该技能。最多叠加 10 层。",
	["Channelling stops when Total Circle Radius reaches 9 metres"] = "当圆圈总范围达到 9 米时停止吟唱",
	["Channelling, Spell, Support"] = "持续吟唱, 法术, 辅助",
	["Channels to build up a large explosion, which is released when you stop using the skill. The longer you channel, the larger the area of effect and damage of the explosion."] = "持续吟唱来施放大型的爆炸。吟唱的时间越长，爆炸的范围与造成的伤害越大。停止使用该技能变会触发爆炸。",
	["Channels to build up an explosion, which is released when you stop using the skill or automatically at maximum stages. The longer you channel, the larger the area of effect and damage of the explosion."] = "持续吟唱来施放一场爆炸。吟唱的时间越长，爆炸的范围与造成的伤害越大。停止使用该技能或达到最大层数时会触发爆炸。",
	["Channels to concentrate an explosion, which is released when you stop using the skill. The longer you channel, the larger the damage of the explosion, but the smaller the area."] = "持续吟唱来汇聚一场爆炸。吟唱的时间越长，爆炸造成的伤害越大，但范围越小。停止使用该技能会触发爆炸。",
