	["Charges at a targeted location or enemy, pushing away enemies in your path and repeatedly dealing off-hand damage in a small area in front of you. You deal damage in a larger area when you reach the target. The further you travel, the more damage you deal, and the greater your chance of stunning enemies."] = "向一个目标位置或敌人冲锋，将路径上的敌人推向两旁，同时对你面前的小范围不断造成副手伤害。当抵达目标时，你对更大范围造成伤害。你穿越的距离越远，造成的伤害就越高，晕眩敌人的几率也越高。",
	["Charges you with lightning which lasts a duration before unleashing, damaging surrounding enemies."] = "在短暂聚能之后释放, 对你周围的敌人造成伤害. 有短暂的冷却时间.",
