	["Corpse Level"] = "灵柩等级",
	["Corpse Life"] = "灵柩生命",
	["Corpse Pact"] = "灵柩契约",
	["Corpse Walk"] = "灵盒行走",
	["Corpse must be the same type as the monster you're fighting."] = "灵柩必须与你正在对抗的怪物属于同一类型。",
	["Corpse must be the same type as the monster you're fighting.\nThis also implies you have 'Consumed a corpse Recently'"] = "灵柩必须与你正在对抗的怪物属于同一类型。\n这也表示你近期内消耗过灵柩",
	["Corpses near the targeted location explode, dealing damage in a small area and creating an orb which detonates after a duration, dealing spell damage in a larger area. The explosion of the corpse is not affected by modifiers to spell damage, and cannot be reflected."] = "使目标附近的灵柩爆炸并造成小范围伤害，召唤一个短时间后引爆的火球，可以造成较大范围的法术伤害。灵柩爆炸造成的伤害无法被法术伤害词缀加成，并且无法被反射。",
	["Corpses near the targeted location explode, dealing damage in a small area and creating an orb which moves towards nearby enemies before dealing spell damage in a larger area. The explosion of the corpse is not affected by modifiers to spell damage, and cannot be reflected."] = "目标附近的灵柩爆炸造成小范围伤害，并召唤一个自动追踪敌人的火球，可以造成较大范围的法术伤害。灵柩爆炸造成的伤害无法被法术伤害词缀加成，并且无法被反射。",
	["Corpses you Spawn have 5% increased Maximum Life"] = "生成的灵柩最大生命提高 5%",
	["Corr Blood Immune"] = "免疫腐化之血",
	["Corrosion"] = "腐蚀",
	["Corrosion has no stack limit"] = "腐蚀没有层数上限",
	["Corrosion lasts 4 seconds and refreshes the duration of existing Corrosion stacks"] = "腐蚀持续 4 秒，并刷新已有腐蚀层数的持续时间",
	["Corrosive Elements"] = "腐蚀元素",
	["Corrosive Hunger"] = "腐蚀饥渴",
