	["Damageable Minions deal 30% increased Damage for each second they have been alive,\nup to a maximum of 150%"] = "可受伤害的召唤生物每存活一秒，造成的伤害提高 30%，\n最多 150%",
	["Damageable Minions take 5% increased Damage for each second they have been alive,\nup to a maximum of 50%"] = "可受伤害的召唤生物每存活一秒，受到的伤害提高 5%，\n最多 50%",
	["Damages enemies in an area, applying a debuff for a short duration. If a non-unique enemy dies while affected by the debuff, the corpse will be consumed to summon a Sentinel of Absolution for a secondary duration, or to refresh the duration and life of an existing one instead if you have the maximum number of them."] = "伤害一片区域内的敌人，在短时间内施加一个减益效果。若受该减益效果影响的非传奇敌人被击败，则消耗它的灵柩来召唤一名持续时间独立的赦罪哨卫。如果你召唤的赦罪哨卫达到数量上限，则刷新其中一个的持续时间和生命值。",
	["Damaging Ailments Cannot Be inflicted on you while you already have one"] = "你已经受到伤害异常状态时不会再受到伤害异常状态",
