	["Desecrated Ground"] = "腐化地面",
	["Desecrates the ground, spawning corpses based on monsters in the current area and dealing chaos damage over time to enemies. If you are using the Raise Spectre skill there is a chance to spawn spectral corpses matching your most recently raised Spectres. Spectral corpses cannot be interacted with except by Minion skills."] = "腐化一块地面，根据当前区域中的怪物召唤灵柩，并持续对敌人造成混沌伤害。若你正在使用召唤灵体技能时，则有几率生成生成与最近召唤的灵体相同的灵体灵柩。灵体灵柩无法与非召唤生物技能互动。",
