	["Enemies Killed near your Banner have 20% chance to Explode, dealing a tenth of their Life as Physical Damage"] = "旗帜周围被击败的敌人有 20% 的几率爆炸，造成其生命十分之一的物理伤害",
	["Enemies Killed with Attack Hits have a 15% chance to Explode, dealing a tenth of their Life as Physical Damage"] = "被攻击击中击败的敌人有 15% 的几率爆炸，造成其生命十分之一的物理伤害",
	["Enemies Killed with Wand Hits have a 10% chance to Explode, dealing a quarter of their Life as Chaos Damage"] = "被法杖击中击败的敌人有 10% 的几率爆炸，造成其生命四分之一的混沌伤害",
