	["For each additional Projectile this skill would fire, create an additional Ghostly Cannon instead"] = "此技能每本应额外发射一枚投射物，改为额外制造一门幽灵火炮",
	["For each nearby corpse, you and nearby Allies Regenerate 0.2% of Energy Shield per second, up to 2.0% per second"] = "周围每个灵柩使你和周围友军每秒再生 0.2% 能量护盾，每秒最多 2.0%",
	["For each nearby corpse, you and nearby Allies Regenerate 5 Mana\nper second, up to 50 per second"] = "周围每个灵柩使你和周围友军每秒再生 5 魔力，每秒最多 50",
	["For nodes with multiple stats this slider controls the weight of the first stat listed."] = "对于拥有多条属性的节点，此滑块控制第一条属性的权重。",
