	["Gain a buff that makes you faster, harder to detect, and grants Phasing, letting you pass through enemies. Performing any skill replaces this buff with one that boosts melee physical damage of skills you use yourself (it will not apply to your melee skills used by totems). Consumes Frenzy Charges to increase duration."] = "使你的身影难以被发现, 且增加你的移动速度. 移动时不再被敌人阻挡. 使用任何技能将移除此增益效果, 并给予你自身另一个增加攻击伤害的短暂增益效果(这个增益不会对你的图腾生效). 可以使用狂怒球延长持续时间.",
	["Gain a random Shrine buff every 10 seconds"] = "每 10 秒获得一个随机神龛增益",
	["Gain an Endurance Charge when you Stun an Enemy with a Melee Hit from Supported Skills"] = "当你使用被辅助技能近战命中并晕眩敌人时，获得 1 个耐力球",
	["Gain an Incubating buff, adding to its Plague Value as you inflict poisons. Use the skill again to begin Infecting, dealing chaos damage over time to nearby enemies until the Plague Value is depleted. Your damage modifiers don't apply to this skill's damage. Using the skill again alternates between Incubating and Infecting."] = "获得一个孕育增益效果，施毒会使其增长瘟疫值。再次使用该技能会使其传染，对周围敌人造成混沌持续伤害，直至瘟疫值耗尽。伤害词缀无法作用于该技能的伤害。请在孕育和传染之间交替使用。",
