	["Grant bonuses to Non-Channelling Skills you use by consuming 3 Charges from a Flask of\neach of the following types, if possible:"] = "从以下可用类型的药剂中各\n消耗 3 充能次数，为非吟唱技能提供加成：",
	["Grants 1 Passive Skill Point"] = "赋予 1 天赋点数",
	["Grants 2 Passive Skill Points"] = "赋予 2 天赋点数",
	["Grants Armour equal to 25% of your Reserved Mana to you and nearby Allies"] = "给予你和周围友军相当于你 25% 保留魔力的护甲",
	["Grants Elusive"] = "获得灵巧",
	["Grants Elusive and a buff that grants Phasing. While you have this buff, monsters that enter an area around you will be Withered. Using a skill or losing the Elusive buff ends this skill's effects. Shares a cooldown with other Blink skills. Cannot be used while already Elusive."] = "获得灵巧和给予迷踪效果的增益效果当你具有该增益效果时，你周围一定范围内的怪物会受到死亡凋零影响。使用技能或灵巧耗尽会终止该技能的效果。和其它闪现技能共用冷却时间。已有灵巧时无法使用。",
	["Grants Glorious Madness. Using this skill again will remove Glorious Madness and the Touched Debuffs it inflicts, but you will be unable to Embrace Madness again until the cooldown expires."] = "获得【疯狂荣光】。重复使用该技能会移除【疯狂荣光】和它施加的【触动】减益效果。在冷却时间结束后可以再次使用【疯狂之拥】。",
	["Grants Insanity"] = "获得错乱效果",
	["Grants Level 1 Embrace Madness Skill"] = "获得 1 级的疯狂之拥技能",
	["Grants Level 20 Affliction Skill"] = "获得 20 级折磨技能",
	["Grants Level 20 Barkskin Skill"] = "获得 20 级树皮御体技能",
	["Grants Level 20 Misty Reflection Skill"] = "赋予 20 级迷雾倒影技能",
	["Grants Level 20 Pacify Skill"] = "获得 20 级宁心技能",
	["Grants Level 20 Penance Mark Skill"] = "获得 20 级忏悔印记技能",
	["Grants Level 20 Ravenous Skill"] = "获得 20 级贪噬技能",
	["Grants Level 20 Summon Dark Effigy Skill"] = "获得 20 级召唤黑暗塑像技能",
	["Grants Level 20 Summon Sentinel of Radiance Skill"] = "获得 20 级的主动技能召唤光辉哨兵",
	["Grants Level 20 Unbound Avatar Skill"] = "获得 20 级不羁化身技能",
	["Grants Phasing"] = "获得迷踪",
	["Grants Summon Greater Harbinger of Directions Skill"] = "获得召唤高等射术先驱者技能",
	["Grants Virulence when you Poison an Enemy"] = "使敌人中毒时获得毒力",
	["Grants a buff adding cold damage to spells and attacks. If you shatter an enemy, this skill will cause them to explode and deal AoE cold damage to enemies near them. This damage is not affected by modifiers to spell damage."] = "获得一个增益效果，给法术和攻击增添冰霜伤害。如敌人被你粉碎，则该技能将其引爆，对周围的敌人造成范围冰霜伤害。该伤害不套用调整法术伤害的词缀。",
	["Grants a buff giving more poison damage and a chance to inflict poison. When you poison an enemy while you have this buff, you gain Virulence, and summon an Agony Crawler minion that uses projectile and area attacks. You will lose Virulence over time, at a rate which increases the more Virulence you have. The minion will die when you have no Virulence."] = "给予一个增益效果，使中毒伤害提高，并有几率造成中毒。当你带有此增益时使敌人中毒，你会获得【毒力】，并且召唤一个会投掷投射物和范围攻击的【苦痛爬行者】。你会持续失去【毒力】，【毒力】越高，失去的速度越快。【毒力】消退后【苦痛爬行者】就会死亡。",
	["Grants a buff providing fire damage based on your physical damage. While you have this buff, if you kill an enemy, other enemies near them will be burned based on the overkill damage. The burn inflicted by this skill can only be affected by modifiers to damage over time (burning damage is damage over time)."] = "于手中凝聚火焰之力, 为物理伤害额外增加火焰伤害. 若是你击败了一个敌人, 溢出的伤害将会以点燃的形式扩散至附近的敌人.该技能引起的燃烧只会受到持续伤害词缀的影响(燃烧属于持续伤害)",
	["Grants a buff which adds lightning damage to spells and attacks. If you kill a shocked enemy, this skill will create a storm, causing lightning bolts to strike enemies around you for a duration. The damage inflicted by this skill is not affected by modifiers to spell damage."] = "获得一个增益效果，给法术和攻击增添闪电伤害。如被击败的是感电的敌人，则该技能会创造一个风暴，在一段时间内用闪电打击你周围的敌人。该技能施加的伤害不套用调整法术伤害的词缀。",
	["Grants a buff which causes you to deal more damage for each Herald skill affecting you. While you have this buff, this skill turns the space around you into a tear in reality, releasing pulses that damage enemies around you. Inflicting Ailments causes you to gain Otherworldly Pressure, which increases the frequency of the pulses. You will lose Otherworldly Pressure over time, at a rate which increases the more of it you have. The damage inflicted by this skill is not affected by modifiers to spell damage."] = "获得一个增益效果，身上每有一个生效的捷技能，就会造成更多伤害。当你拥有这个增益时，该技能会将周围的空间会化为一道现实裂口，释放脉冲伤害你周围的所有敌人。你对敌人施加异常状态时，会为你堆叠【异界威压】，从而提高裂口内脉冲的频率。异界威压会随时间逐渐流失，并且威压越强，流失的速度就越快。该技能施加的伤害无法被法术伤害词缀加成。",
	["Grants a buff which lets you deal more physical damage. When you kill an enemy while you have this buff, this skill will summon a Sentinel of Purity, or refresh the duration and life of an existing one instead if you have the maximum number of them. The Sentinels of Purity have a single-target melee attack and an area melee attack."] = "获得一个增益效果，使你造成更多物理伤害。在该效果下击败敌人后，该技能会召唤一个【纯净哨兵】，如【纯净哨兵】已经达到上限，则刷新其中一个的持续时间和生命值。【纯净哨兵】会使用单人近战攻击和范围近战攻击。",
	["Grants a buff which significantly lowers your maximum Energy Shield to transform your equipped swords into swords formed from that energy. Casting the spell again removes the buff. This skill cannot be triggered or used with non-sword weapons."] = "获得一个增益效果，它会大幅降低你的能量护盾，用于将你装备的剑变为一把能量之刃。再次施放该法术会移除此增益。需要剑类武器发动。该技能无法被触发。",
	["Grants maximum Energy Shield equal to 10% of your Reserved Mana to\nyou and nearby Allies"] = "给予你和周围友军等同你 10% 魔力保留的额外能量护盾",
	["Grants up to maximum Blood Charges"] = "获得最大赤炼球上限",
