	["Grants your Sentinel Minion as Aura that grants\n\t+23% to Chaos Resistance"] = "为你的哨兵召唤生物提供光环，效果为：\n\t+23% 混沌抗性",
	["Grants your Sentinel Minion as Aura that grants\n\t30% increased Mana Regeneration Rate"] = "为你的哨兵召唤生物提供光环，效果为：\n\t魔力再生速度提高 30%",
	["Grants your Sentinel Minion as Aura that grants\n\t50% reduced Effect of Curses on you"] = "为你的哨兵召唤生物提供光环，效果为：\n\t你受到的诅咒效果降低 50%",
	["Grants your Sentinel Minion as Aura that grants\n\tGain 15% of Physical Damage as Extra Fire Damage"] = "为你的哨兵召唤生物提供光环，效果为：\n\t获得等同于物理伤害 15% 的额外火焰伤害",
	["Grants your Sentinel Minion as Aura that grants\n\tGain 15% of Physical Damage as Extra Lightning Damage"] = "为你的哨兵召唤生物提供光环，效果为：\n\t获得等同于物理伤害 15% 的额外闪电伤害",
