	["Hits Stun as though dealing 50% more Melee Fire Damage"] = "击中造成相当于近战火焰伤害总增 50% 的晕眩效果",
	["Hits against Brittle enemies have up to +6% Critical Strike Chance."] = "对脆弱敌人的击中最多获得 +6% 暴击几率。",
	["Hits against Brittle enemies have up to +6% Critical Strike Chance.\nThis option will also allow you to input the effect of Brittle."] = "对脆弱敌人的击中最多获得 +6% 暴击几率。\n同时允许输入脆弱效果。",
	["Hits against you Cannot be Critical Strikes if you've been Stunned Recently"] = "若你近期被眩晕，击中你时无法暴击",
