	["Hits before death"] = "死亡前可承受击中次数",
	["Hits enemies, converting some of your physical damage to chaos damage and inflicting poison which will be affected by modifiers to skill duration. If dual wielding, deals the damage of both weapons in one strike. Requires a claw, dagger or sword."] = "击中敌人，将部分物理伤害转化为混沌伤害，并使敌人中毒。该技能受技能持续时间词缀影响。双持武器时会使用两把武器同时攻击并造成伤害。限定爪类、匕首与剑类。",
	["Hits enemies, converting some of your physical damage to chaos damage and inflicting poison which will be affected by modifiers to skill duration. If dual wielding, will strike with both weapons. Requires a claw, dagger or sword."] = "击中敌人，将部分部分物理伤害转化为混沌伤害，并使敌人中毒。该技能受技能持续时间词缀影响。双持武器时会用两把武器同时攻击。限定爪类、匕首与剑类。",
	["Hits enemies, converting some of your physical damage to cold damage. If a non-unique enemy is frozen and is on less than one third life, they will shatter when hit by Glacial Hammer. If striking three times in a row, the third strike will freeze enemies more easily. Requires a Mace, Sceptre or Staff."] = "凝聚冰霜之力，转换一部分的物理伤害为冰霜伤害以重击敌人。若受到攻击的非传奇敌人被冻结且生命少于 1/3，则被冰霜之锤命中时会碎成冰屑。如连续攻击三次，则第三次冻结敌人的几率更高。限定锤类、短杖或长杖。",
	["Hits enemies, converting some of your physical damage to cold damage. If striking three times in a row, the third strike will be a critical strike. Requires a Mace, Sceptre or Staff."] = "凝聚冰霜之力，转换一部分的物理伤害为冰霜伤害以重击敌人。如连续攻击三次，则第三次必定爆击。限定锤类、短杖或长杖。",
	["Hits enemies, converting some of your physical damage to cold damage. It traps enemies with you in a circle of ice so that they can't escape. Requires a Mace, Sceptre or Staff."] = "凝聚冰霜之力，转换一部分的物理伤害为冰霜伤害以重击敌人，同时在敌人周围造成一个让敌人无法逃脱的冰墙。限定锤类、短杖或长杖。",
	["Hits from Supported Skills grant Cruelty"] = "被辅助技能的击中提供凌厉效果",
	["Hits froms Supported Skills cannot kill Enemies"] = "被辅助技能的击中无法消灭敌人",
	["Hits have 10% chance to ignore Enemy Physical Damage Reduction"] = "击中有 10% 的几率忽略敌方怪物的物理伤害减免",
	["Hits have 15% chance to ignore Enemy Physical Damage Reduction"] = "击中有 15% 的几率忽略敌方怪物的物理伤害减免",
	["Hits have 15% chance to treat Enemy Monster Elemental Resistance values as inverted"] = "击中有 15% 的几率将敌方怪物的元素抗性视作反转",
	["Hits have 20% chance to deal 50% more Area Damage"] = "击中有 20% 的几率造成总增 50% 的范围伤害",
	["Hits have 30% chance to deal 50% more Area Damage"] = "击中有 30% 的几率造成总增 50% 的范围伤害",
