	["Hits have 35% chance to ignore Enemy Physical Damage Reduction"] = "击中有 35% 的几率忽略敌方怪物的物理伤害减免",
	["Hits have 50% chance to ignore Enemy Physical Damage Reduction"] = "击中有 50% 的几率忽略敌方怪物的物理伤害减免",
	["Hits ignore Enemy Physical Damage Reduction"] = "击中无视敌人的物理伤害减免",
	["Hits that Stun Enemies have Culling Strike"] = "造成敌人晕眩的击中带有终结效果",
	["Hits that deal Elemental Damage remove Exposure to those Elements and inflict Exposure to other Elements\nExposure inflicted this way applies -25% to Resistances"] = "元素伤害击中时移除该种元素曝露，并施加其它元素曝露\n通过这种方式施加的元素曝露使其抗性 -25%",
	["Hits that fail to Freeze due to insufficient Freeze Duration inflict Hoarfrost"] = "冻结时间不足而未能造成冻结的击中会造成白霜",
	["Hits that would Ignite instead Scorch"] = "击中造成的点燃改为造成烧灼",
	["Hits treat Enemy Monster Elemental Resistance values as inverted"] = "击中将敌方怪物的元素抗性视作反转",
	["Hits with Supported Skills for which the highest Damage Type is Elemental cause you to gain 25 Resonance of other Elements per second for 2 seconds"] = "被辅助技能击中时，造成最高伤害的元素类型会提供 25 点其它元素的共振效果，持续 2 秒",
	["Hits with Supported Skills for which the highest Damage Type is Elemental cause you to gain 25 Resonance of other Elements per second for 2 seconds\nLose 5 Resonance per second of each Element you are not gaining"] = "被辅助技能击中时，造成最高伤害的元素类型会提供 25 点其它元素的共振效果，持续 2 秒\n每有一种没有获得共振效果的元素使你每秒失去 5 点共振",
	["Hits with Supported Skills for which the highest Damage Type is Lightning, Physical or Chaos cause you to gain 25 Unholy Resonance of the other types per second for 2 seconds"] = "被辅助技能的击中造成最高伤害的类型为闪电、物理或混沌时，每秒为你提供 25 点其它类型的邪恶共振，持续 2 秒",
	["Hits with Supported Skills for which the highest Damage Type is Lightning, Physical or Chaos cause you to gain 25 Unholy Resonance of the other types per second for 2 seconds\nLose 5 Unholy Resonance per second of each type you are not gaining"] = "被辅助技能的击中造成最高伤害的类型为闪电、物理或混沌时，每秒为你提供 25 点其它类型的邪恶共振，持续 2 秒\n每有一种未获得的邪恶共振类型，每秒失去 5 点该类型的邪恶共振",
