	["In addition to allowing 'against Blinded Enemies' modifiers to apply,"] = "除启用对致盲敌人生效的词缀外，",
	["In addition to allowing 'against Blinded Enemies' modifiers to apply,\n Blind applies the following effects.\n -20% Accuracy \n -20% Evasion"] = "除启用对致盲敌人生效的词缀外，\n 致盲施加以下效果。\n 命中值 -20%\n 闪避值 -20%",
	["In addition to allowing any 'against Shocked Enemies' modifiers to apply,"] = "除启用对感电敌人生效的词缀外，",
	["In addition to allowing any 'against Shocked Enemies' modifiers to apply,\nthis will allow you to input the effect of the Shock applied to the enemy."] = "除启用对感电敌人生效的词缀外，\n此处可输入施加于敌人的感电效果。",
	["In addition to allowing any 'while Elusive' modifiers to apply,"] = "除启用拥有灵巧时生效的词缀外，",
	["In addition to allowing any 'while Elusive' modifiers to apply,\nthis will enable the Elusive buff itself:\n\t15% Chance to Avoid all Damage from Hits\n\t30% increased Movement Speed\nThe effect of Elusive decays over time."] = "除启用拥有灵巧时生效的词缀外，\n启用灵巧增益本身：\n\t有 15% 的几率避免击中的全部伤害\n\t移动速度提高 30%\n灵巧效果随时间衰减。",
	["In addition to allowing any 'while on Consecrated Ground' modifiers to apply,"] = "除启用位于奉献地面时生效的词缀外，",
	["In addition to allowing any 'while on Consecrated Ground' modifiers to apply,\nConsecrated Ground grants 5% Life Regeneration to players and allies."] = "除启用位于奉献地面时生效的词缀外，\n奉献地面使玩家和友军每秒再生 5% 生命。",
	["In addition to allowing any 'while you have Arcane Surge' modifiers to apply,"] = "除启用拥有秘术增强时生效的词缀外，",
	["In addition to allowing any 'while you have Arcane Surge' modifiers to apply,\nthis will enable the Arcane Surge buff itself. (Grants 20% increased cast speed and 30% increased Mana Regeneration rate)"] = "除启用拥有秘术增强时生效的词缀外，\n启用秘术增强增益本身。（施法速度提高 20%，魔力再生率提高 30%）",
	["In addition to allowing any 'while you have Onslaught' modifiers to apply,"] = "除启用拥有猛攻时生效的词缀外，",
	["In addition to allowing any 'while you have Onslaught' modifiers to apply,\nthis will enable the Onslaught buff itself. (Grants 20% increased Attack, Cast, and Movement Speed)"] = "除启用拥有猛攻时生效的词缀外，\n启用猛攻增益本身。（攻击、施法及移动速度提高 20%）",
	["In addition to allowing any 'while you have Tailwind' modifiers to apply,"] = "除启用拥有提速尾流时生效的词缀外，",
	["In addition to allowing any 'while you have Tailwind' modifiers to apply,\nthis will enable the Tailwind buff itself. (Grants 8% increased Action Speed)"] = "除启用拥有提速尾流时生效的词缀外，\n启用提速尾流增益本身。（行动速度提高 8%）",
	["In addition to allowing any 'while your minions have Onslaught' modifiers to apply,"] = "除启用召唤生物拥有猛攻时生效的词缀外，",
