	["Jump a short distance through the air, damaging and knocking back enemies with your weapon where you land. Enemies you would land on are pushed out of the way. Requires an Axe, Mace, Sceptre, Sword or Staff."] = "短途飞跃，落地时用武器对敌人造成伤害，并击退敌人。被踩到的敌人会被推出去。限定斧类、锤类、短杖、剑类或长杖。",
	["Jump through the air, damaging and knocking back enemies with your weapon where you land. Enemies you would land on are pushed out of the way. Requires an Axe, Mace, Sceptre, Sword or Staff."] = "一跃而起，落地时用武器对敌人造成伤害，并击退敌人。被踩到的敌人会被推出去。限定斧类、锤类、短杖、剑类或长杖。",
