	["Must support both a channelling skill and a non-channelling spell skill to work. The channelling skill will trigger a spell periodically while channelling. Cannot support skills used by totems, traps, or mines. Vaal skills and skills with a reservation cannot be triggered."] = "必须同时辅助一个持续吟唱技能和一个非吟唱法术技能。吟唱技能在吟唱过程中每隔一段时间会触发一个法术技能。无法辅助图腾、陷阱或地雷施放的技能。瓦尔技能和有保留效果的技能无法被触发。",
	["Must support both a melee attack skill and a spell skill to work. The attack skill will trigger a spell when it kills an enemy. Cannot support totems, traps, or mines. Vaal skills, channelling skills, and skills with a reservation cannot be triggered."] = "必须同时辅助一个攻击技能和一个法术技能。法术技能会在攻击技能击败敌人时触发。无法辅助图腾、陷阱或地雷。瓦尔技能、持续吟唱类技能和有保留效果的技能无法被触发。",
	["Must support both a skill that creates minions which can be damaged, and"] = "必须同时辅助一个能够产生可受到伤害的召唤生物技能，以及",
	["Must support both a skill that hits enemies, and a hex curse skill to work. The hex will be applied when enemies are hit by the other skill. Cannot support totems, traps, or mines. Minions cannot apply hexes this way."] = "必须同时辅助一个击中敌人的技能和一个魔蛊诅咒。该魔蛊会在敌人被另一技能击中时施加给它们。无法辅助图腾、陷阱和地雷。召唤生物不能通过这种方式施加魔蛊。",
	["Must support both an attack skill and a spell skill to work. The attack skill will trigger a spell when it critically strikes an enemy. Cannot support totems, traps, or mines. Vaal skills, channelling skills, and skills with a reservation cannot be triggered."] = "必须同时辅助一个攻击技能和一个法术技能。法术技能会在攻击技能对敌人造成暴击时触发。无法辅助图腾、陷阱或地雷。瓦尔技能、持续吟唱类技能和有保留效果的技能无法被触发。",
