	["Overprepared"] = "过度准备",
	["Override to the percent chance for the secondary projectiles to hit, default of 60% or 80% with helm enchant. (20% per secondary projectile)"] = "覆盖次级投射物的命中几率，默认为 60%，拥有头部附魔时为 80%（每个次级投射物 20%）",
	["Overrides Windows DPI scaling inside Path of Building.\nChoose a percentage between 100% and 250% or revert to the system default."] = "覆盖程序内部的 Windows 显示缩放。\n可选择 100% 至 250%，或恢复系统默认值。",
	["Overrides the automatically calculated Life of the minion supported by Companionship."] = "覆盖自动计算的忠诚伙伴辅助召唤生物生命。",
	["Overrides the automatically calculated Life of your Sentinel of Radiance that can be taken before yours."] = "覆盖自动计算的光辉哨兵可为你先行承受伤害的生命。",
	["Overrides the automatically calculated Life of your Stone Golem of Safeguarding that can be taken before yours."] = "覆盖自动计算的卫护之召唤巨石魔像可为你先行承受伤害的生命。",
	["Overrides the automatically calculated Life of your Vaal Rejuvenation Totem that can be taken before yours."] = "覆盖自动计算的瓦尔回春图腾可为你先行承受伤害的生命。",
	["Overrides the automatically calculated Life of your nearest Totem (excluding Vaal Rejuvenation Totem) that can be taken before yours (used by Totem Mastery)."] = "覆盖自动计算的最近图腾（不含瓦尔回春图腾）可为你先行承受伤害的生命，用于图腾专精。",
	["Overrides the automatically calculated total Life of your Spectres that can be taken before yours (used by Jinxed Juju)."] = "覆盖自动计算的幽魂可为你先行承受伤害的总生命，用于厄运护符。",
	["Overrides the automatically calculated total Life of your Void Spawns that can be taken before yours."] = "覆盖自动计算的虚空后裔可为你先行承受伤害的总生命。",
	["Overrides the default hex colour for highlighting nodes in passive tree search. \nExpected format is 0x000000. "] = "覆盖天赋搜索中高亮节点的默认颜色。\n格式应为 0x000000。\n",
	["Overrides the default hex colour for negative values in breakdowns. \nExpected format is 0x000000. "] = "覆盖计算明细中负数的默认颜色。\n格式应为 0x000000。\n",
	["Overrides the default hex colour for positive values in breakdowns. \nExpected format is 0x000000. "] = "覆盖计算明细中正数的默认颜色。\n格式应为 0x000000。\n",
