	["Perform a spinning attack, damaging enemies around you and creating a bladestorm matching your stance. The bladestorm repeatedly damages enemies, based on your weapon damage and attack time, for a duration. Blood bladestorms are stationary and cause Bleeding, while Sand bladestorms move slowly forwards and Blind enemies. Requires a Sword or Axe. You are in Blood Stance by default."] = "发动一次旋转攻击，对你周围的敌人反复造成伤害，并根据你的姿态创造剑刃风暴，根据你的武器伤害和攻击速度对敌人造成伤害，并持续一段时间。血姿态下的剑刃风暴静止不动，并造成流血状态。沙姿态下的剑刃风暴会缓慢向前移动，并致盲敌人。需要剑类和斧类。默认为血姿态。",
	["Perform a spinning attack, damaging enemies around you and creating a random bladestorm. The bladestorm repeatedly damages enemies, based on your weapon damage and attack time, for a duration. Blood bladestorms are stationary and cause Bleeding, while Sand bladestorms move slowly forwards and Blind enemies. Requires a Sword or Axe."] = "发动一次旋转攻击，对你周围的敌人造成伤害，并随机产生一种剑刃风暴，根据你的武器伤害和攻击速度对敌人反复造成伤害，并持续一段时间。血之剑刃风暴静止不动，并造成流血状态。沙之剑刃风暴会缓慢向前移动，并将敌人致盲。需要剑类和斧类。",
	["Perform a strike with a melee weapon that gives the character a frenzy charge if it hits. Frenzy charges increase your attack speed."] = "使用近战武器进行一次打击，若是命中敌人则累积一颗狂怒球。带着狂怒球的状态下将会增加你的攻击速度。",
	["Performs a melee attack, and causes lightning to strike a nearby enemy, dealing damage in an area. Each target can only be hit once by this skill. Hitting an enemy grants an aura for a duration. Requires a Sword, Axe, Mace, Sceptre, Staff or Unarmed."] = "发动一次近战攻击，用闪电攻击周围的一个敌人，造成范围伤害。每个目标只能被该技能击中一次。击中敌人时使你获得光环并持续一段时间。限定剑类、斧类、锤类、短杖、长杖或空手。",
	["Performs a melee attack, and causes lightning to strike nearby enemies, dealing damage in an area. Each target can only be hit once by this skill. Requires a Sword, Axe, Mace, Sceptre, Staff or Unarmed."] = "发动一次近战攻击，用闪电攻击周围的敌人，造成范围伤害。每个目标只能被该技能击中一次。限定剑类、斧类、锤类、短杖、长杖或空手。",
	["Performs a series of quick teleports towards a targeted location, stopping if you would overlap with monsters or terrain. If using the \"Attack in Place\" option, the direction is reversed. Shares a cooldown with other Blink skills. Cannot be supported."] = "朝目标方向发起一连串快速传送，与怪物或地形重叠时停止。如果使用“原地攻击”，会朝反方向传送。和其它闪现技能共用冷却时间。无法被辅助。",
	["Performs a series of quick teleports towards a targeted location. If using the \"Attack in Place\" option, the direction is reversed. Shares a cooldown with other Blink skills."] = "朝目标方向发起一连串快速传送。如果使用“原地攻击”，会朝反方向传送。和其它闪现技能共用冷却时间。",
	["Performs a warcry, taunting all nearby enemies to attack the user and exerting subsequent strike attacks. The user and nearby allies gain a buff that  grants elemental resistances."] = "发出一声战吼，嘲讽全部周围的敌人，吸引他们攻击，增助随后的打击攻击。使自身和友军获得一个增益，提高元素抗性。",
	["Performs a warcry, taunting all nearby enemies to attack the user and granting a buff to the user and nearby allies. The user and allied players also gain endurance charges."] = "发出一声战吼，嘲讽周围的敌人，吸引他们攻击，并使自身和周围的友军获得增益。自身和友军还会获得耐力球。",
	["Performs a warcry, taunting nearby enemies to attack the user and exerting subsequent attacks. Nearby allies gain a buff based on the damage of your weapon."] = "发出一声战吼，嘲讽周围的敌人，吸引他们攻击，并增助随后的攻击。同时基于你的武器伤害给队友施加一个增益效果。",
	["Performs a warcry, taunting nearby enemies to attack the user and exerting subsequent attacks. The user and nearby allies gain a buff that boosts critical strike chance."] = "发出一声战吼，嘲讽周围的敌人，吸引他们攻击，增助随后的攻击。使自身和友军获得一个增益，提高暴击几率。",
	["Performs a warcry, taunting nearby enemies to attack the user and exerting subsequent attacks. The user and nearby allies gain a buff that grants a portion of their physical damage as extra fire damage. In addition to being taunted, enemies are inflicted with a secondary debuff causing them to explode when they die, dealing fire damage in an area."] = "发出一声战吼，嘲讽周围的敌人，吸引他们攻击，并增助随后的攻击。使自身和友军获得一个增益，获得相当于部分物理伤害的额外火焰伤害。除了嘲讽，敌人还会受到次级减益效果，使其在被击败时爆炸，造成范围火焰伤害。",
	["Performs a warcry, taunting nearby enemies to attack the user and exerting subsequent attacks. The user and nearby allies gain a buff that grants movement speed."] = "发出一声战吼，嘲讽周围的敌人，吸引他们攻击，增助随后的攻击。使自身和友军获得一个增益，提高移动速度。",
	["Performs a warcry, taunting nearby enemies to attack the user and exerting subsequent slam attacks. The user and nearby allies gain a buff that increases their armour and stun threshold."] = "发出一声战吼，嘲讽周围的敌人，吸引他们攻击，并增助随后的攻击。使自身和友军获得一个增益，提高护甲和晕眩阈值。",
	["Performs a warcry, taunting nearby enemies to attack the user, and summoning Mirage Warriors from nearby corpses. The Mirage Warriors each use a linked attack skill once before dissipating."] = "发出一声战吼，嘲讽周围的敌人，吸引它们的攻击，同时利用周围的灵柩召唤蜃影武士。每个蜃影武士都会在消散前使用链接的攻击技能。",
	["Performs an attack with a ranged weapon that gives the character a frenzy charge if it hits. Frenzy charges increase your attack speed."] = "使用远程武器进行一次攻击，若是命中敌人则累积一颗狂怒球。带着狂怒球的状态下将会增加你的攻击速度。",
	["Performs two fast strikes with a melee weapon, each of which summons a double of you for a duration to continuously attack monsters in this fashion."] = "使用近战武器发动两次快速打击，每次都会召唤出你的影分身持续一段时间，并用相同的方式连续攻击敌人。",
	["Performs two fast strikes with a melee weapon, gaining stages which cause this skill to attack faster. All stages are lost when you move."] = "使用近战武器发动两次快速打击，积累层数并加快该技能的攻击速度。移动时失去所有层数。",
	["Performs two fast strikes with a melee weapon."] = "使用近战武器发动两次快速打击。",
	["Permanently Afflicts any of your damageable minions in a targeted area, causing them to take physical damage over time, at an accelerating rate. Each such minion causes you to regenerate life at a rate based on the current damage of it's Affliction debuff. Afflicted Minions explode if their life is lowered to a fifth of maximum."] = "对你在目标区域中的可受到伤害的召唤生物施加永久性折磨，使其受到越来越高的物理伤害。每个受到该效果影响的召唤生物使你获得生命再生，效果根据折磨减益的当前伤害决定。受折磨的召唤生物的生命值低于五分之一时会爆炸。",
