	["Place a Frost Shield that drains your energy shield for one second or until you run out, gaining stages while this drain occurs. The Frost Shield takes some damage from hits in place of you and allies while in its area. Enemies in the area are Chilled. You can only have one Frost Shield active at once."] = "放置一个冰霜护盾。它会在一秒内耗尽你的能量护盾，或者将能量护盾用尽，并在耗尽时提供层数。当你和友军在其中时，冰霜护盾会承受部分击中伤害，并冰缓其中的敌人。同时只能启动一个冰霜护盾。",
	["Placed duration of Mine / Traps"] = "地雷／陷阱放置时间",
	["Placement speed"] = "放置速度",
	["Places a Sigil on the ground, which grants a buff to you and allies in the area around it for a duration. The Sigil gains stages as you spend mana in its area, making the buff more powerful. You can only have one Sigil of Power at a time."] = "在地上放置法印，当你和友军站在其中时候给你们提供增益效果，并持续一段时间。你在其中消耗魔力会给法印积累层数，强化增益效果。同时只能有一个威能法印。",
