	["Raise two spectral spiders from each nearby corpse that will attack your enemies with Viper Strike. Each raised spider grants you increased Attack Speed and increased Damage with Poison. Enemies will not engage the spiders directly, and they are immune to damage."] = "周遭每具灵柩召唤两只幽魂巨蛛, 他们将扑向你的敌人. 敌人将不会主动攻击你的蜘蛛.",
	["Raise your hand to the \nroaring crowd and pledge \nyour allegiance to glory."] = "在喧哗的群众前举起你的手，\n向荣耀宣誓。",
	["Raised Beast Spectres have 3 additional modifiers randomly chosen in each Area"] = "复苏的野兽灵体在每个区域中随机获得 3 个额外词缀",
