	["Raised Zombies have 5% chance to Taunt Enemies on Hit"] = "复苏的魔卫有 5% 的几率击中时嘲讽敌人",
	["Raises a spectral version of a defeated foe as a minion to fight for you in battle."] = "唱名唤魂，从目标灵柩唤醒其灵体并使它为你而战.",
	["Raises a spectral version of a defeated foe as a temporary minion to fight for you in battle for a duration."] = "唱名唤魂，从目标灵柩唤醒其临时灵体，并使它在一段时间内为你而战。",
	["Raises a zombie minion from a corpse, which will follow you and attack enemies with a melee strike and an area of effect slam."] = "从一个灵柩中复苏一只魔卫，它会跟随你并攻击敌人。魔卫会近战打击，也会使用一种无法闪避的范围猛击。",
	["Raises a zombie minion from a corpse, which will follow you and attack enemies with a melee strike."] = "从一个灵柩中复苏一只魔卫，它会跟随你并攻击敌人。魔卫会近战打击。",
	["Raises necromantic energies into the sky above a targeted location, where they coalesce into a zombie minion. The minion then attacks by falling to the ground, causing an impact that deals damage in an area. The zombie cannot survive the impact."] = "将亡灵魔法射向目标位置的上空，汇聚成一只魔卫。该魔卫会坠击地面，造成范围冲击伤害。该魔卫无法在坠击中幸存。",
