	["Removes all Mana"] = "移除所有魔力",
	["Removes all mana\n10% more maximum Life\nSkills Cost Life instead of Mana\nSkills Reserve Life instead of Mana"] = "移除所有魔力\n生命上限总增 10%\n技能消耗生命而非魔力\n保留生命而非魔力",
