	["Reparse all the inputs in case they have been disabled or they have changed since loading the build or importing"] = "重新解析所有输入，以应用加载构筑或导入后发生的更改，或恢复被禁用的输入。",
	["Repeat Count"] = "重复次数",
	["Repeat Mode"] = "重复模式",
	["Repeatedly attacks a large area in different directions. Each Vaal Reave that hits an enemy grants stages, which you will begin to lose after a short period without hitting anything. Only works with Daggers, Claws, and One-Handed Swords."] = "攻击不同方向的大片区域。击中敌人的每道瓦尔冲击波都会积累阶段，只要短期内没有击中任何目标就会失去阶段。 限定匕首，爪类，单手剑。",
	["Repeatedly fires a piercing projectile based on your weapon, converting some physical damage to fire. The projectiles form an arc in front of you."] = "发射一个定必穿透敌人的你的武器的复制品或是投射物的投射物. 此技能有短暂冷却时间.",
	["Repeatedly hit enemies in a circle in front of you while channelling, dealing damage to and around the enemy. The critical strike chance is continually boosted while channelling. You unleash an additional hit for each stage reached once the channelling ends. Requires a Dagger, Claw or One-Handed Sword."] = "持续吟唱时反复击中前方圆周范围内的敌人，对周围敌人造成伤害。暴击率会随吟唱持续增加。吟唱结束时会根据吟唱的层数额外施放一次击中。限定匕首、爪类、或单手剑。",
	["Repeatedly hit enemies in a circle in front of you while channelling, dealing damage to and around the enemy. The damage is continually boosted while channelling. You unleash an additional hit for each stage reached once the channelling ends. Requires a Dagger, Claw or One-Handed Sword."] = "持续吟唱时反复击中前方圆周范围内的敌人，对周围敌人造成伤害。伤害会随吟唱持续增加。吟唱结束时会根据吟唱的层数额外施放一次击中。限定匕首、爪类、或单手剑。",
	["Repeatedly teleports to enemies and hits them, inflicting a wound but dealing no damage. After the repeating finishes, each enemy is hit by the total damage of their wounds, which are removed."] = "不断传送到敌人身边并攻击它们，对其施加割伤但不造成伤害。传送结束后，每个敌人受到身上割伤的总伤害并移除它们的割伤。",
