	["Set and Forget"] = "高枕无忧",
	["Set the default level of your builds. If this is higher than 1, manual level mode will be enabled by default in new builds."] = "设置新构筑的默认等级。若高于 1，新构筑默认启用手动等级模式。",
	["Set the default quality that can be overwritten by build-related quality settings in the skill panel."] = "设置默认宝石品质；技能面板中构筑专属的品质设置可覆盖此值。",
	["Sets a marker at a location. After a short duration, a bolt strikes the marker, dealing physical damage around it and causing bolts to strike at any other markers you've cast. Bolt impacts will leave behind a pool of boiling blood, which deals physical damage over time to enemies within it for a secondary duration."] = "在目标区域设置一个标记。经过一小段时间后，闪电会攻击那个标记，对其周围造成物理伤害，同时使闪电攻击你施放的其他标记。闪电的冲击留下一片沸血，在一定时间内对其中的敌人持续造成物理伤害。",
	["Sets a marker at a location. After a short duration, lightning strikes the marker, dealing damage around it and causing lightning strikes at any other markers you've cast."] = "在目标区域设置一个标记。经过一小段时间后，闪电会攻击那个标记，对其周围造成伤害，同时使闪电攻击你施放的其他标记。",
	["Sets a marker at a location. Lightning strikes random enemies around the marker repeatedly over the skill's duration, dealing damage in an area around the strike. Modifiers to the skill's duration will also affect the delay between these strikes. When the duration ends, a large bolt of lightning strikes the marker, dealing damage around it."] = "在目标区域设置一个标记. 当标记存在时, 闪电将会随机攻击标记附近的敌人, 对其造成伤害. 该技能的持续时间也会影响闪电发射的间隔。经过一小段时间后, 强力的闪电会攻击那个标记, 并对该标记周围的敌人造成伤害, 同时其他的标记也会陆续受到闪电攻击.",
	["Sets current number of Bleeds on the enemy if using the Crimson Dance keystone."] = "使用绯红舞蹈核心天赋时，设置敌人身上的当前流血层数。",
	["Sets current number of Bleeds on the enemy if using the Crimson Dance keystone.\nThis also implies that the enemy is Bleeding."] = "使用绯红舞蹈核心天赋时，设置敌人身上的当前流血层数。\n这也表示敌人正在流血。",
	["Sets the EHP calc to not apply gain on block, suppress or Defiance of Destiny effects"] = "有效生命计算不应用格挡／压制时的获取效果，也不应用命运之抗争的效果",
	["Sets the EHP calc to pretend its unlucky and reduce the effects of random events such as"] = "让有效生命计算按不幸情形处理，降低以下随机事件的效果：",
	["Sets the EHP calc to pretend its unlucky and reduce the effects of random events such as\n\tBlock/Spell Block Chance\n\tDodge/Spell Dodge Chance\n\tSpell Suppression Chance\n\tAvoidance Chance"] = "让有效生命计算按不幸情形处理，降低以下随机事件的效果：\n\t攻击／法术格挡几率\n\t攻击／法术躲避几率\n\t法术伤害压制率\n\t避免伤害几率",
	["Sets the amount of resonance on the lowest element."] = "设置最低元素的共鸣数量。",
	["Sets the amount of unholy resonance on the lowest element."] = "设置最低元素的不洁共鸣数量。",
	["Sets the blade count for Blade Vortex skills used by spectres."] = "设置幽魂使用的飞刃风暴刀刃数量。",
	["Sets the blade count for Blade Vortex skills used by spectres.\nDefault is 1; maximum is 5."] = "设置幽魂使用的飞刃风暴刀刃数量。\n默认值为 1；上限为 5。",
	["Sets the level of Assassin's Mark to apply to the player."] = "设置施加于玩家的刺客印记等级。",
	["Sets the level of Conductivity to apply to the player."] = "设置施加于玩家的导电等级。",
	["Sets the level of Despair to apply to the player."] = "设置施加于玩家的绝望等级。",
	["Sets the level of Elemental Weakness to apply to the player."] = "设置施加于玩家的元素要害等级。",
	["Sets the level of Elemental Weakness to apply to the player.\nIn mid tier maps, 'of Elemental Weakness' applies level 10.\nIn high tier maps, 'of Elemental Weakness' applies level 15."] = "设置施加于玩家的元素要害等级。\n中阶地图的元素要害词缀施加 10 级诅咒。\n高阶地图的元素要害词缀施加 15 级诅咒。",
	["Sets the level of Enfeeble to apply to the player."] = "设置施加于玩家的衰弱等级。",
	["Sets the level of Enfeeble to apply to the player.\nIn mid tier maps, 'of Enfeeblement' applies level 10.\nIn high tier maps, 'of Enfeeblement' applies level 15."] = "设置施加于玩家的衰弱等级。\n中阶地图的衰弱词缀施加 10 级诅咒。\n高阶地图的衰弱词缀施加 15 级诅咒。",
	["Sets the level of Flammability to apply to the player."] = "设置施加于玩家的易燃等级。",
	["Sets the level of Frostbite to apply to the player."] = "设置施加于玩家的冻伤等级。",
	["Sets the level of Poacher's Mark to apply to the player."] = "设置施加于玩家的盗猎者印记等级。",
	["Sets the level of Projectile Weakness to apply to the player."] = "设置施加于玩家的投射物要害等级。",
	["Sets the level of Punishment to apply to the player."] = "设置施加于玩家的惩戒等级。",
	["Sets the level of Temporal Chains to apply to the player."] = "设置施加于玩家的时空锁链等级。",
	["Sets the level of Temporal Chains to apply to the player.\nIn mid tier maps, 'of Temporal Chains' applies level 10.\nIn high tier maps, 'of Temporal Chains' applies level 15."] = "设置施加于玩家的时空锁链等级。\n中阶地图的时空锁链词缀施加 10 级诅咒。\n高阶地图的时空锁链词缀施加 15 级诅咒。",
	["Sets the level of Vulnerability to apply to the player."] = "设置施加于玩家的脆弱等级。",
	["Sets the level of Vulnerability to apply to the player.\nIn mid tier maps, 'of Vulnerability' applies level 10.\nIn high tier maps, 'of Vulnerability' applies level 15."] = "设置施加于玩家的脆弱等级。\n中阶地图的脆弱词缀施加 10 级诅咒。\n高阶地图的脆弱词缀施加 15 级诅咒。",
	["Sets the level of Warlord's Mark to apply to the player."] = "设置施加于玩家的督军印记等级。",
	["Sets the maximum Life of the Skeleton that is being targeted."] = "设置目标魔侍的生命上限。",
	["Sets the maximum life of the target corpse for Detonate Dead and similar skills."] = "设置爆灵术及类似技能所用目标灵柩的生命上限。",
	["Sets the maximum life of the target corpse for Detonate Dead and similar skills.\nFor reference, a level 70 monster has "] = "设置爆灵术及类似技能所用目标灵柩的生命上限。\n作为参考，70 级怪物拥有：",
	["Sets the maximum life of the target minion for Communion."] = "设置神圣宗派的目标召唤生物生命上限。",
	["Sets the number of active Spectral Tigers."] = "设置当前生效的幽虎数量。",
	["Sets the number of active Spectral Tigers.\nThe base maximum number of Spectral Tigers is 5."] = "设置当前生效的幽虎数量。\n幽虎的基础数量上限为 5。",
	["Sets the number of active Spectral Wolves."] = "设置当前生效的幽狼数量。",
