	["Sets the number of active Spiders."] = "设置当前生效的蜘蛛数量。",
	["Sets the number of active Spiders.\nThe base maximum number of Spiders is 20."] = "设置当前生效的蜘蛛数量。\n蜘蛛的基础数量上限为 20。",
