	["Skills Supported by Nightblade have 40% increased Effect of Elusive"] = "被夜刃辅助的技能的灵巧效果提高 40%",
	["Skills Supported by Unleash have 20% increased Seal gain frequency"] = "技能被释出辅助时，其封印获取频率提高 20%",
