	["Skills from Equipped Main Hand Weapon are supported by level 1 Cruelty"] = "装备的主手武器上的技能受到 1 级凌厉辅助",
	["Skills gain Added Chaos Damage equal to 25% of Life Cost, if Life Cost is not higher than the maximum you could spend"] = "如果生命消耗不高于你能够消耗的最大值，技能附加相当于生命消耗 25% 的混沌伤害",
	["Skills gain a Base Life Cost equal to 100% of Base Mana Cost"] = "技能获得等于基础魔力消耗100%的基础生命消耗",
	["Skills is Detonated targeting an Enemy"] = "此技能引爆时会以一名敌人为目标",
	["Skills supported by Unleash have +1 to maximum number of Seals"] = "技能被释出辅助时 +1 封印数量上限",
	["Skills supported by Unleash have +3 to maximum number of Seals"] = "技能被释出辅助时 +3 封印数量上限",
	["Skills that Summon a Totem have 30% chance to Summon two Totems instead of one"] = "可以召唤一个图腾的技能有 30% 的几率改为召唤两个图腾",
	["Skills that have dealt a Critical Strike in the past 8 seconds deal 40% more Elemental Damage with Hits and Ailments\nYour Critical Strikes do not deal extra Damage\nAilments never count as being from Critical Strikes"] = "在过去 8 秒内你造成暴击的技能造成的元素击中和异常状态伤害总增 40%\n你的暴击不造成额外伤害\n暴击造成的异常状态不在其内",
	["Skills used by Mines deal 30% increased Area Damage if you Detonated a Mine Recently"] = "若你近期内引爆过地雷，则地雷类技能造成的范围伤害提高 30%",
	["Skills used by Mines have 10% increased Area of Effect"] = "地雷类技能的效果区域扩大 10%",
	["Skills used by Mines have 15% increased Area of Effect if you Detonated a Mine Recently"] = "若你近期内引爆过地雷，则地雷类技能的效果范围扩大 15%",
	["Skills used by Totems deal 10% more Damage per maximum number of Summoned Totems"] = "图腾使用的技能造成的伤害按召唤图腾数量上限总增 10%",
	["Skills used by Totems have 10% more Area of Effect per maximum number of Summoned Totems"] = "图腾使用的技能的效果区域按召唤图腾数量上限总增 10%",
	["Skills used by Traps have 15% increased Area of Effect"] = "陷阱所使用的技能范围扩大 15%",
	["Skills used by Traps have 50% increased Area of Effect"] = "陷阱所使用的技能范围扩大 50%",
	["Skills which Throw Traps have +1 Cooldown Use"] = "陷阱投掷技能 +1 冷却时间次数",
	["Skills which create Brands have 35% chance to create an additional Brand"] = "产生烙印的技能有 35% 的几率产生一个额外烙印",
	["Skitterbots"] = "召唤飞掠者",
	["Skittering Runes"] = "飞掠符文",
	["Skull Cracking"] = "碎颅",
	["Skullbreaker"] = "碎颅斗士",
	["Slam the ground, calling down a Holy Hammer from above. On hitting an enemy, another Hammer will cascade forward, repeating if further enemies are hit, up to a cap. A Power Charge can be expended to call down additional Hammers to either side of the initial slam. Requires a Mace, Sceptre or Staff."] = "猛击地面，从空中召唤一柄神圣之锤。命中敌人时，会有另一柄锤子向前落下；若继续命中其他敌人则会重复此过程，直到达到上限。可以消耗一个暴击球以在初始猛击两侧召唤额外的神圣之锤。需要装备锤、短杖或长杖。",
	["Slam the ground, consuming all Endurance Charges and unleashing a fiery fissure in front of you, dealing area damage and randomly releasing a number of smaller fissures branching off from it. Requires a Mace, Sceptre, Sword, Axe, Staff, or Unarmed."] = "猛击地面，消耗所有耐力球，在前方制造一道灼热的裂缝，造成范围伤害，并随机分出一些更小的裂缝。需要锤类、短杖、剑类、斧类、长杖或徒手发动。",
	["Slam the ground, consuming all Power Charges and calling down a cascade of holy hammers from above in an outward spiral. Further hammers are called down for each Power Charge consumed. Requires a Mace, Sceptre or Staff."] = "砸击地面，消耗所有暴击球，并从天召唤一系列神圣之锤，以向外盘旋的形式倾泻而落。每消耗 1 个暴击球便会额外召唤更多锤子。需要钉锤、短杖或长杖。",
	["Slam the ground, creating a winding fissure that deals area damage while travelling outwards. When it reaches the target location it erupts dealing damage in an area. After erupting, the fissure continues moving towards enemies to cause further eruptions. Requires an Axe, Mace, Sceptre, Staff or Unarmed."] = "猛击地面，生成一个向外延伸的同时造成范围伤害的曲折裂缝。裂缝会在抵达目标地点时喷发，喷发之后，裂缝会继续朝敌人移动，造成进一步的喷发。需要斧类、锤类、短杖，长杖或空手。",
	["Slam the ground, creating a winding fissure that deals area damage while travelling outwards. When it reaches the target location it erupts, releasing a burst of molten projectiles. After erupting, the fissure continues moving towards enemies to cause further eruptions. Requires an Axe, Mace, Sceptre, Staff or Unarmed."] = "猛击地面，生成一个向外延伸的同时造成范围伤害的曲折裂缝。裂缝会在抵达目标地点时喷发，释放出熔岩投射物。喷发之后，裂缝会继续朝敌人移动，造成进一步的喷发。需要斧类、锤类、短杖，长杖或空手。",
	["Slam the ground, creating a winding fissure that deals area damage while travelling outwards. When it reaches the target location it erupts, releasing a burst of molten projectiles. Requires an Axe, Mace, Sceptre, Staff or Unarmed."] = "猛击地面，生成一个向外延伸的同时造成范围伤害的曲折裂缝。裂缝会在抵达目标地点时喷发，释放出熔岩投射物。需要斧类、锤类、短杖，长杖或空手。",
	["Slam the ground, damaging enemies in an area around the impact in three stages of increasing size. Enemies take slightly less damage on the second and third stage, and can only be hit by one stage. Works with Swords, Maces, Sceptres, Axes, Staves and Unarmed."] = "猛击地面，对递增范围内的敌人造成三段冲击伤害。敌人受到的第二段和第三段伤害的伤害较低，并且只能被一段伤害击中。限定剑类、锤类、短杖、斧类、长杖和空手。",
	["Slam the ground, damaging enemies in an area. Slams with main hand weapon deal more damage. Slams with off hand weapon have larger area of effect. Requires dual-wielding Swords, Maces, Sceptres, or Axes to use."] = "猛击地面，对范围内的敌人造成伤害。主手武器的猛击会造成更高的伤害。副手武器的猛击效果范围更大。限定双持剑类、锤类、短杖或斧类武器。",
	["Slam the ground, sending out a rectangular fissure that deals area damage to enemies and thrusts a large spike from the ground where it ends. Warcries or other Slam Attacks performed by you or allied players near the spike will cause it to shatter, damaging surrounding enemies. Works with Maces, Sceptres, Axes, Staves and Unarmed."] = "猛击地面，发出一道长方形裂缝，对敌人造成范围伤害。裂缝尽头会伸出大型尖刺。你或任何友方玩家在尖刺附近使用战吼或其它猛击技能都会让它破碎，对周围敌人造成伤害。需要锤类、短杖、斧类、长杖、徒手发动。",
	["Slam the ground, sending out rectangular fissures that deal area damage to enemies and thrust a spike from the ground when they end. The spikes shatter after a duration, damaging surrounding enemies. Works with Maces, Sceptres, Axes, Staves and Unarmed."] = "猛击地面，发出长方形裂缝，对敌人造成范围伤害。裂缝尽头会伸出尖刺。尖刺会在一段时间后破碎，对周围敌人造成伤害。需要锤类、短杖、斧类、长杖、徒手发动。",
	["Slam the ground, sending out rectangular fissures that deal area damage to enemies and thrust a spike from the ground when they end. Warcries or other Slam Attacks performed by you or allied players near any spike will cause them to shatter, damaging surrounding enemies. Works with Maces, Sceptres, Axes, Staves and Unarmed."] = "猛击地面，发出长方形裂缝，对敌人造成范围伤害。裂缝尽头会伸出尖刺。你或任何友方玩家在尖刺附近使用战吼或其它猛击技能都会让它们破碎，对周围敌人造成伤害。需要锤类、短杖、斧类、杖类、徒手发动。",
	["Slam the ground, unleashing a fiery fissure in front of you, dealing area damage and randomly releasing a number of smaller fissures branching off from it. Consume an Endurance Charge every third time you slam the ground with this skill. Requires a Mace, Sceptre, Sword, Axe, Staff, or Unarmed."] = "猛击地面，在前方制造一道灼热的裂缝，造成范围伤害，并随机分出一些更小的裂缝。用该技能每三次猛击地面都会消耗一个耐力球。需要锤类、短杖、剑类、斧类、长杖或徒手发动。",
	["Slam, Attack, Melee, AoE, Support"] = "猛击, 攻击, 近战, 效果区域, 辅助",
	["Slam, Support, Melee, Attack, Strike"] = "猛击, 辅助, 近战, 攻击, 打击",
	["Slams the ground at a targeted location. If an enemy is near where you target, you'll teleport to it from a short distance away, slam, and create an area of consecrated ground. Can't be supported by Multistrike, and requires a Sword, Axe, Mace, Sceptre, Staff or Unarmed."] = "重击目标地点。若目标周围有敌人，你可以短距离传送到它旁边，用一道猛击创造一片奉献地面。无法被多重打击辅助。限定剑类、斧类、锤类、短杖、长杖或空手。",
	["Slams the ground at a targeted location. If an enemy is near where you target, you'll teleport to it from a short distance away, slam, and create an area of consecrated ground. The cooldown can be bypassed by expending an Endurance Charge. Can't be supported by Multistrike, and requires a Sword, Axe, Mace, Sceptre, Staff or Unarmed."] = "重击目标地点。若目标周围有敌人，你可以短距离传送到它旁边，用一道猛击创造一片奉献地面。消耗一个耐力球能重置其冷却时间。无法被多重打击辅助。限定剑类、斧类、锤类、短杖、长杖或空手。",
	["Slams the ground in front of you, creating a wave that travels forward and damages enemies with an increased chance to stun. The wave deals more damage to closer enemies. Requires an Axe, Mace, Sceptre, Staff or Unarmed."] = "猛击地面，制造一道向前的冲击波，对敌人造成伤害，并有较高的几率击晕敌人。敌人距离越近则冲击波伤害越高。需要斧类、锤类、短杖、长杖、徒手发动。",
	["Slams the ground in front of you, creating a wave that travels in all directions that damages enemies with an increased chance to stun. The wave deals more damage to closer enemies. Requires an Axe, Mace, Sceptre, Staff or Unarmed."] = "猛击地面，制造出一道向四面八方扩散的冲击波，对敌人造成伤害并使其晕眩。敌人距离越近则冲击波伤害越高。需要斧类、锤类、短杖、长杖、徒手发动。",
	["Slams the ground in front of you, creating a wide wave that travels forward and damages enemies with an increased chance to stun. Requires a Two Handed Axe, Two Handed Mace, or Staff."] = "猛击地面，制造一道向前的宽阔冲击波，对敌人造成伤害，并有较高的几率击晕敌人。需要双手斧、双手锤或长杖发动。",
	["Slams the ground, creating a slow wave of churning terrain that damages enemies in a sequence of areas in front of you. A number of enemies hit by the wave will release a shockwave, damaging other enemies around them. Using the skill again will stop the previous wave. Requires a Mace, Sceptre, Axe, Staff or Unarmed."] = "猛击地面，产生一道缓慢的冲击波，按照前进顺序伤害你前方的敌人。一定数量的敌人被冲击波击中后会向周围其它敌人施放伤害性震波。再次使用该技能会使之前的冲击波会停止。需要锤类、短杖、斧类、长杖、徒手发动。",
	["Slams the ground, creating a slow wave of churning terrain that damages enemies in a sequence of areas in front of you. A number of enemies hit by the wave will release a shockwave, damaging other enemies around them. Using the skill again will stop the previous wave. When the wave reaches a target or terrain, it can restart aiming towards an enemy, if one is in range. Requires a Mace, Sceptre, Axe, Staff or Unarmed."] = "猛击地面，产生一道冲击波，接连对前方一定范围内的敌人造成伤害。一定数量的敌人被冲击波击中后会向周围其它敌人施放伤害性震波。再次使用该技能会使之前的冲击波停止。当冲击波抵达目标或地形障碍时，若范围内有敌人，可重新锁定目标。需要锤类、短杖、斧类、长杖或徒手。",
	["Slams the ground, creating a wave of churning terrain that damages enemies in a sequence of areas in front of you. A number of enemies hit by the wave will release a shockwave, damaging other enemies around them. Requires a Mace, Sceptre, Axe, Staff or Unarmed."] = "猛击地面，产生一道冲击波，接连对前方一定范围内的敌人造成伤害。一定数量的敌人被冲击波击中后会向周围其它敌人施放伤害性震波。需要锤类、短杖、斧类、长杖、徒手发动。",
	["Slashes twice, releasing waves of force that damage enemies they hit. Enemies in the middle of the slashes can be hit by both. Requires a One Handed Axe or One Handed Sword."] = "挥斩两次，释放出对敌人造成伤害的冲击波。在挥斩中间的敌人会被击中两次。限定单手斧或单手剑。",
	["Slashes twice, releasing waves of force that damage enemies they hit. Enemies in the middle of the slashes can be hit by both. The slashes will have a chance to inflict bleeding in Blood Stance, or have a wider angle in Sand Stance. Can be used with Axes and Swords. You are in Blood Stance by default."] = "挥斩两次，释放出对敌人造成伤害的冲击波。在挥斩中间的敌人会被击中两次。挥斩在血姿态下有一定几率施加流血效果，在沙姿态下拥有更宽的角度。限定斧类和剑类。默认为血姿态。",
	["Slashes twice, releasing wide waves of force that damage enemies they hit. Enemies in the middle of the slashes can be hit by both. Requires a Two Handed Axe or Two Handed Sword."] = "挥斩两次，释放出对敌人造成伤害的宽广冲击波。在挥斩中间的敌人会被击中两次。限定双手斧或双手剑。",
