	["Small"] = "小型",
	["Small Explosions"] = "小型爆炸",
	["Small Jewel Socket"] = "小型珠宝槽",
	["Smaller explosions have between 30% reduced and 30% increased base radius at random"] = "小爆炸的基础范围在降低 30% 至提高 30% 之间随机浮动",
	["Smash the ground to bring forth multiple spears to damage enemies. When in Blood Stance, multiple spikes burst from the ground in sequence, able to hit enemies multiple times. In Sand Stance, the spikes are thrust outwards. Requires a Sword or Axe. You are in Blood Stance by default."] = "重击地面，产生前进的多重尖刺伤害敌人。在血姿态下，多重尖刺会依次爆发，多次击中敌人。在沙姿态下，尖刺会朝外推进。限定剑类或斧类。默认为血姿态。",
	["Smash the ground to bring forth multiple spikes from the ground in sequence, able to hit enemies multiple times."] = "重击地面，产生接连爆发的多重尖刺，可以击中敌人多次。",
	["Smashes the ground, dealing damage in an area and cracking the earth. The crack will erupt in a powerful aftershock after a duration. Cracks created before the first one has erupted will not generate their own aftershocks. Requires an Axe, Mace, Sceptre, Staff or Unarmed."] = "猛击地面，对周围造成大量伤害，并在地面上留下裂隙。一段时间过后，地面的裂隙将会释放冲击波造成更多的伤害。在冲击波还未释放前再次使用技能不会刷新地面的裂隙。需要斧类、锤类、短杖、长杖、徒手发动。",
	["Smashes the ground, dealing damage in an area and cracking the earth. The crack will erupt in a powerful aftershock after a short duration. After using this skill, your steps will deal damage around you, cracking the earth if the previous cracks have erupted. This effect ends after a secondary duration, or after a maximum number of aftershocks. Requires an Axe, Mace, Sceptre, Staff or Unarmed."] = "猛击地面，对周围造成大量伤害，并在地面上留下多处裂隙。短时间后，裂隙会喷发出三股强大的震波。使用此技能后，你的脚步会对你周围的区域造成伤害，若之前的裂隙已经喷发，则会再次造成裂隙。该效果会在第二次持续结束后消退，或是在震波喷发至最大数量后消退。需要斧类、锤类、短杖、长杖、徒手发动。",
