	["Spellbreaker"] = "破魔者",
	["Spells Cast by Totems have 4% increased Cast Speed"] = "图腾所使用法术的施法速度加快 4%",
	["Spells Cast by Totems have 5% increased Cast Speed"] = "图腾所使用法术的施法速度加快 5%",
	["Spells Cast by Totems have 8% increased Cast Speed"] = "图腾所使用法术的施法速度加快 8%",
	["Spells cast by Totems deal 25% increased Damage"] = "图腾施放的法术造成的伤害提高 25%",
	["Spells which can gain Intensity have +1 to maximum Intensity"] = "能获得凝聚的法术的最大凝聚 +1",
	["Spells you cast yourself gain Added Physical Damage equal to 75% of Life Cost, if Life Cost is not higher than the maximum you could spend"] = "如果生命消耗不高于你能够消耗的最大值，你自己施放的法术附加相当于生命消耗 75% 的物理伤害",
	["Spellslinger"] = "法术节魔",
	["Spend Energy Shield before Mana for Skill Mana Costs\nEnergy Shield protects Mana instead of Life\n50% less Energy Shield Recharge Rate"] = "消耗魔力的技能在消耗魔力前先消耗能量护盾\n能量护盾保护魔力而非生命\n能量护盾充能率总降 50%",
	["Spendable"] = "可消耗量",
	["Spends a portion of your mana to grant a buff that takes some of the damage from hits for you until depleted. The buff grants added lightning damage based on the amount of mana spent by this skill. Shares a cooldown with other Guard skills."] = "消耗部分魔力，获得一个增益效果，在耗尽前承受部分击中伤害。该增益根据该技能消耗的魔力数量获得额外闪电伤害。和其它防卫技能共用冷却时间。",
	["Spider's Web"] = "蜘蛛网",
	["Spiked Bulwark"] = "荆刺守护",
	["Spiked Concoction"] = "钉刺调和",
	["Spin and attack in place, damaging nearby enemies and pulling others towards you. While using this skill, you cannot be stunned or knocked back. Cannot be supported by Ruthless."] = "以自体为中心在原地进行旋转攻击，周围的敌人将会被拉向你并受到伤害。使用此技能时，无法被晕眩或被击退，无法被无情辅助。",
	["Spin with a sword or axe to deal damage in an area around you. If you have at least 10 rage, create a ragestorm attached to you that repeatedly deals attack damage to enemies inside based on your attack speed. The ragestorm consumes rage at an accelerating rate, and ends if you run out."] = "用刀剑或斧类施放旋转攻击，若你拥有至少 10 点怒火，则会产生一道附着于你的怒火风暴，根据你的攻击速度反复对其中的敌人造成攻击伤害。怒火风暴消耗怒火的速度之间加快，并在耗尽怒火时结束。",
	["Spin with a sword or axe to deal damage in an area around you. Sacrifices some rage to send a ragestorm forward. While enemies are inside it, the ragestorm will slow its movement and repeatedly deal attack damage based on your attack speed."] = "用刀剑或斧类施放旋转攻击，对周围范围内的敌人造成伤害。牺牲部分怒火可以朝前方发射一道怒火风暴。在怒火风暴内的敌人会降低移动速度，并根据你的攻击速度反复承受攻击伤害。",
