	["Strike your foes down with a powerful blow."] = "对你的敌人无情痛击.",
	["Strikes enemies in front of you with a surge of flame. Burning enemies are dealt more damage. If you hit an ignited enemy, will create burning ground under them. Your damage modifiers don't apply to this burning ground."] = "用汹涌的火焰打击前方的敌人。燃烧的敌人会受到更高伤害。如击中被点燃的敌人，则会在它身下产生燃烧地面。你的伤害词缀不能作用于燃烧地面。",
	["Strikes enemies in front of you with a surge of flame. If this ignites an enemy a large area of burning ground will be created under them. Your damage modifiers don't apply to this burning ground."] = "用汹涌的火焰打击前方的敌人。如果点燃了敌人，则会在它身下产生大片燃烧地面。你的伤害词缀不能作用于燃烧地面。",
	["Strong Arm"] = "强壮手臂",
	["Stronger Pulses always Critically Strike"] = "强力脉冲必定暴击",
