	["Stun Chance"] = "晕眩几率",
	["Stun Duration"] = "晕眩持续",
	["Stun Duration per Endurance Charge"] = "每个耐力球的眩晕持续时间",
	["Stun Mastery"] = "眩晕专精",
	["Stun Recovery"] = "晕眩回复",
	["Stun Support"] = "击晕(辅)",
	["Stun Threshold"] = "晕眩阈值",
	["Stun Threshold Reduction"] = "晕眩门坎降低",
	["Stunned while Casting Recently?"] = "近期内是否在施放法术时被晕眩？",
	["Stuns from Critical Strikes have 100% increased Duration"] = "暴击造成的眩晕效果持续时间延长 100%",
