	["Summon Harbinger of Brutality"] = "召唤残暴先驱者",
	["Summon Harbinger of Directions"] = "召唤射术先驱者",
	["Summon Harbinger of Focus"] = "召唤不屈先驱者",
	["Summon Harbinger of Storms"] = "召唤冰雷先驱者",
	["Summon Harbinger of Time"] = "召唤时空先驱者",
