	["Surprise Sabotage"] = "惊奇破坏",
	["Surround yourself with the dead,\nso that you may avoid joining them."] = "与亡者同行，方能不变亡灵。",
	["Surveillance"] = "洞若观火",
	["Survivalist"] = "死里逃生",
	["Sustainable Trauma"] = "可维持内伤层数",
	["Svalinn Cast on Block"] = "斯瓦林：格挡时施放",
	["Swagger"] = "双刃之舞",
	["Swap"] = "切换",
	["Swift Affliction"] = "极速腐化(辅)",
	["Swift Affliction Support"] = "极速腐化(辅)",
	["Swift Assembly"] = "迅整（辅）",
	["Swift Assembly Support"] = "迅整（辅）",
	["Swift Killer"] = "敏捷克星",
	["Swift Venoms"] = "迅速致毒",
	["Swiftbrand"] = "迅猛烙印（辅）",
	["Swiftbrand Support"] = "迅猛烙印（辅）",
	["Swiftness"] = "迅捷",
	["Swiftness # of Momentum Removed"] = "迅捷所移除的动量层数",
	["Swing an Axe or Sword, consuming Steel Shards to gain a Steel Ward that protects you for a duration, and fire projectiles which shatter on impact or soon after being launched, dealing area damage in front of where they shatter. Steel Shards are gained with the Call of Steel Skill."] = "挥舞斧类或剑类，消耗【钢刃碎片】，产生一个保护你一段时间的钢刃结界。它会发射投射物，并在撞击或发射后不久粉碎，对前方敌人造成范围伤害。钢刃碎片由【钢铁呼唤】技能提供。",
	["Swing an Axe or Sword, firing projectiles which shatter on impact or soon after being launched, dealing area damage in front of where they shatter."] = "挥舞斧类或剑类并发射投射物，在撞击或发射后不久粉碎，对前方敌人造成范围伤害。",
	["Swing your wand to cause a number of projectiles to rain down within a large area in front of you, directly targeting the locations of enemies in the area. The locations where each projectile will land are shown with markers before they fall. Each projectile explodes when hitting the ground, dealing area damage and triggering Kinetic Anomaly. Cannot be used by Totems, Traps, or Mines."] = "挥动法杖在前方大范围内降下多个投射物，可直接锁定区域内敌人的位置。所有投射物在落地前会显示预判落点标记，触地时爆炸造成范围伤害，并触发动能异变技能。此技能无法被陷阱、地雷或图腾使用。",
	["Swing your wand to cause a number of projectiles to rain down within a large area in front of you, directly targeting the locations of enemies in the area. The locations where each projectile will land are shown with markers before they fall. Each projectile explodes when hitting the ground, dealing area damage."] = "挥动法杖在前方大范围内降下多发投射物，直接锁定区域内敌人的位置。所有投射物在落地前会显示预判落点标记，触地时爆炸造成范围伤害。",
	["Swings a two handed mace or a staff in a circle, calling down holy hammers to land randomly on a number of enemies struck. Hits from these holy hammers cannot be evaded."] = "用双手锤或长杖画圈挥舞，召唤神圣之锤随机落在被击中的数个敌人身上。这些神圣之锤造成的击中无法被闪避。",
	["Swings a two handed mace or a staff in a circle, calling down waves of holy hammers for a duration. Cannot be supported by Multistrike."] = "用双手锤或长杖画圈挥舞，在一段时间内持续召唤神圣之锤波浪。无法被多重打击辅助。",
	["Swipe your shield, dealing area damage in three waves in front of you. Enemies can be hit by two of the waves where they overlap."] = "挥舞盾牌，朝你面前造成三道范围伤害的冲击波。敌人可以被两道交叠的冲击波伤害。",
	["Sword Accuracy and Critical Strike Chance"] = "剑类命中值和暴击率",
	["Sword Attacks deal 10% increased Damage with Ailments"] = "剑类攻击造成的异常状态伤害提高 10%",
	["Sword Attacks deal 10% increased Damage with Hits and Ailments"] = "剑类攻击造成的击中和异常状态伤害提高 10%",
	["Sword Attacks deal 12% increased Damage with Hits and Ailments"] = "剑类攻击造成的击中和异常状态伤害提高 12%",
	["Sword Attacks deal 14% increased Damage with Ailments"] = "剑类攻击造成的异常状态伤害提高 14%",
	["Sword Attacks deal 14% increased Damage with Hits and Ailments"] = "剑类攻击造成的击中和异常状态伤害提高 14%",
	["Sword Attacks deal 16% increased Damage with Ailments"] = "剑类攻击造成的异常状态伤害提高 16%",
	["Sword Attacks deal 20% increased Damage with Ailments"] = "剑类攻击造成的异常状态伤害提高 20%",
	["Sword Attacks deal 24% increased Damage with Hits and Ailments"] = "剑类攻击造成的击中和异常状态伤害提高 24%",
	["Sword Attacks deal 30% increased Damage with Hits and Ailments"] = "剑类攻击造成的击中和异常状态伤害提高 30%",
