	["Sword Damage and Attack Speed"] = "剑的伤害和攻击速度",
	["Sword Damage and Block"] = "剑类伤害和格挡",
	["Sword Damage and Melee Range"] = "剑类伤害和近战范围",
	["Sword Mastery"] = "剑类专精",
	["Swordstorm"] = "落刃风暴",
	["Synthesised Item"] = "追忆物品",
	["TAS Lock"] = "安全保护状态",
	["TEMPLAR"] = "圣堂武僧",
	["Tags"] = "标签",
	["Tailwind"] = "提速尾流",
	["Tainted Endurance Charges"] = "污秽耐力球",
	["Tainted Frenzy Charges"] = "污秽狂怒球",
	["Tainted Power Charges"] = "污秽暴击球",
	["Tainted blood is a gift that must be shared."] = "污血之赐应当与人共享。",
	["Take 25% less Damage"] = "受到的伤害总降 25%",
	["Take 40% less Damage from Hits"] = "受到的击中伤害总降 40%",
	["Take 50% less Damage over Time if you've started taking Damage over Time in the past second\n100% more Duration of Ailments on you"] = "若你在过去一秒内开始受到持续伤害，则受到的持续伤害总降 50%\n你身上的异常状态持续时间总增 100%",
	["Take less Physical and Elemental Damage for a short time. Consumes up to 5 Endurance Charges to lengthen the buff and further lessen Physical Damage taken. Shares a cooldown with other Guard skills."] = "短期内受到的物理伤害和元素伤害降低。最多消耗 5 个耐力球使增益效果持续更久，并进一步降低受到的物理伤害。和防卫技能共用冷却时间。",
	["Take no Extra Damage from Critical Strikes if you have Equipped Gloves with no Socketed Gems"] = "若已装备的手套没有镶嵌宝石，则免疫暴击的额外伤害",
	["Taken"] = "承受的伤害",
	["Taken As"] = "承受伤害转化为",
	["Taken As Percent"] = "转为该类型承受的比例",
	["Taken Chaos dmg"] = "承受的混沌伤害",
	["Taken Cold dmg"] = "承受的冰霜伤害",
	["Taken Fire Damage from enemy Hit Recently?"] = "近期内是否受到过敌人击中的火焰伤害？",
	["Taken Fire dmg"] = "承受的火焰伤害",
	["Taken From Block"] = "格挡承伤比例",
	["Taken Lightning dmg"] = "承受的闪电伤害",
	["Taken Phys dmg"] = "承受的物理伤害",
	["Taken as Chaos"] = "转为混沌承伤",
	["Taken as Cold"] = "转为冰霜承伤",
	["Taken as Fire"] = "转为火焰承伤",
	["Taken as Lightning"] = "转为闪电承伤",
	["Taken as Physical"] = "转为物理承伤",
	["Taking Elemental Damage instead heals you and Nearby Allies"] = "将你与周围友军受到的元素伤害转化为回复生命",
	["Taking Elemental Damage instead heals you and Nearby Allies\nYou and Nearby Allies cannot gain Vaal Souls"] = "将你与周围友军受到的元素伤害转化为回复生命\n你与周围友军无法获得瓦尔之灵",
	["Talisman Mods:"] = "魔符词缀：",
	["Talisman Tier"] = "魔符阶级",
	["Targets a corpse, and deals spell damage to enemies around the corpse, as well as causing the corpse to explode, dealing fire damage. The explosion is not affected by modifiers to spell damage and cannot be reflected."] = "对一个灵柩施法，使其周围目标都受到一个法术伤害。同时使该灵柩爆炸， 对附近的敌人造成火焰伤害。爆炸造成的伤害无法被法术伤害词缀加成，并且无法被反射。",
	["Targets a corpse, and deals spell damage to enemies around the corpse, as well as causing the corpse to explode, dealing fire damage. The explosion is not affected by modifiers to spell damage and cannot be reflected. This will continue to target other corpses in the area, with a shorter delay between each one, until it runs out of corpses or has destroyed 8 corpses. Cannot be supported by Spell Cascade."] = "对一个灵柩施法，使其周围目标都受到一个法术伤害。同时使该灵柩爆炸，对附近的敌人造成火焰伤害。爆炸造成的伤害无法被法术伤害词缀加成，并且无法被反射。爆炸会继续指定区域内的其他灵柩，每个灵柩之间的爆炸间隔较短，直到灵柩消耗殆尽或有 8 个灵柩被引爆。无法被多重范围施法辅助。",
	["Targets a corpse, and deals spell damage to enemies around the corpse, as well as causing the corpse to explode, dealing fire damage. The explosion is not affected by modifiers to spell damage and cannot be reflected. This will continue to target other corpses in the area, with an increasing delay between each one, until it runs out of corpses or has destroyed 22 corpses."] = "对一个灵柩施法，使其周围目标都受到一个法术伤害。同时使该灵柩爆炸， 对附近的敌人造成火焰伤害。爆炸造成的伤害无法被法术伤害词缀加成，并且无法被反射。爆炸会继续指定区域内的其他灵柩，每个灵柩之间的爆炸间隔持续延长，直到灵柩消耗殆尽或有 22 个灵柩被引爆。",
	["Targets a corpse, causing it to explode, dealing fire damage. The explosion is not affected by modifiers to spell damage and cannot be reflected. Cannot target corpses that have been created by skills."] = "对一个灵柩施法并使其爆炸，造成火焰伤害。爆炸造成的伤害无法被法术伤害词缀加成，并且无法被反射。无法选择由技能创造的灵柩。",
	["Targets affected by Maim you inflict cannot deal Critical Strikes"] = "受到你施加的残废影响的目标无法造成暴击",
	["Targets an allied player to apply a buff which links you to them for a duration. While linked, their hits can trigger your supported spells. If the target dies while linked, you will also die. This skill cannot be triggered, or used by Totems, Traps, or Mines."] = "同一名友方玩家产生羁绊并持续一段时间。在羁绊期间，羁绊对象可以触发你辅助的法术。若羁绊对象在此期间被击败，你也会同时被击败。该技能不能由图腾、陷阱、地雷施放，也不能被触发。",
	["Targets an allied player to apply a buff which links you to them for a duration. While linked, they copy your block chance and recover life when they block. If the target dies while linked, you will also die. This skill cannot be triggered, or used by Totems, Traps, or Mines."] = "同一名友方玩家产生羁绊并持续一段时间。在羁绊期间，羁绊对象会复制你的格挡率，并在格挡时回复生命。若羁绊对象在此期间被击败，你也会同时被击败。该技能不能由图腾、陷阱、地雷施放，也不能被触发。",
	["Targets an allied player to apply a buff which links you to them for a duration. While linked, they deal additional fire damage based on your life. If the target dies while linked, you will also die. This skill cannot be triggered, or used by Totems, Traps, or Mines."] = "同一名友方玩家产生羁绊并持续一段时间。在羁绊期间，羁绊对象按照你的生命造成额外火焰伤害。若羁绊对象在此期间被击败，你也会同时被击败。该技能不能由图腾、陷阱、地雷施放，也不能被触发。",
	["Targets an allied player to apply a buff which links you to them for a duration. While linked, they get recovery from your life leech instead of you. If the target dies while linked, you will also die. This skill cannot be triggered, or used by Totems, Traps, or Mines."] = "同一名友方玩家产生羁绊并持续一段时间。在羁绊期间，你的生命偷取改为给羁绊对象恢复生命。若羁绊对象在此期间被击败，你也会同时被击败。该技能不能由图腾、陷阱、地雷施放，也不能被触发。",
	["Targets an allied player to apply a buff which links you to them for a duration. While linked, they use your main hand critical strike chance. If the target dies while linked, you will also die. This skill cannot be triggered, or used by Totems, Traps, or Mines."] = "同一名友方玩家产生羁绊并持续一段时间。在羁绊期间，羁绊对象可以使用你的主手暴击率。若羁绊对象在此期间被击败，你也会同时被击败。该技能不能由图腾、陷阱、地雷施放，也不能被触发。",
	["Targets an allied player to apply a buff which links you to them for a duration. While linked, your Energy Shield will intercept some of the damage they would take. If the target dies while linked, you will also die. This skill cannot be triggered, or used by Totems, Traps, or Mines."] = "同一名友方玩家产生羁绊并持续一段时间。在羁绊期间，你的能量护盾可以为羁绊对象阻挡一部分伤害。若羁绊对象在此期间被击败，你也会同时被击败。该技能不能由图腾、陷阱、地雷施放，也不能被触发。",
	["Targets an area and builds up stages in that area based on cast speed. It explodes every 3 stages, until it reaches a maximum of 15. As it gains more stages, the area gets smaller but the damage gets higher."] = "指定一片区域，根据施法速度在其中叠加层数。每 3 层爆炸一次，最多叠满 15 层。层数叠加期间，范围会逐渐缩小，但伤害会逐渐提高。",
	["Tarred Ground"] = "污油地面",
	["Tasalio's Blessing"] = "塔赛里奥的祝福",
	["Tasalio, Cleansing Water"] = "塔赛里奥，纯净之水",
