	["Violent Retaliation"] = "狂暴催化",
	["Violently destroys your body and recreates it at the location of a targeted enemy or corpse, dealing spell damage in an area at both locations. If there is no specific target, it will prioritise corpses over enemies. If targeting a corpse, the corpse will also explode, dealing damage around it that is not affected by modifiers to spell damage, and cannot be reflected. This spell cannot be repeated."] = "摧毁自己的身体，在选取的敌人或灵柩的位置重生，对一片区域内造成法术伤害。如果没有选取目标，它会优先以灵柩为目标。如果以灵柩为目标，该灵柩会爆炸，对周围造成伤害，该伤害不受法术伤害的词缀影响，也不会被反射。该法术无法重复。",
	["Violently destroys your body and recreates it at the location of a targeted enemy or damageable minion, dealing spell damage in an area at both locations. If there is no specific target, it will prioritise minions over enemies. If targeting a minion, the minion will also be destroyed in an explosion which deals damage around it that is not affected by modifiers to spell damage, and cannot be reflected. This spell cannot be repeated."] = "摧毁自己的身体，在选取的敌人或可伤害的召唤生物的位置重生，在起始与目标区域内造成法术伤害。如果没有选取目标，它会优先以召唤生物为目标。如果以召唤生物为目标，该召唤生物会被摧毁并对周围造成伤害，该伤害不受法术伤害的词缀影响，也不会被反射。该法术无法重复。",
