	["Waits for a duration before teleporting to a targeted destination, with the duration based on the distance and your movement speed. When the teleport occurs, lightning damage is dealt to the area around both where the player was and where they teleported to. Casting again will queue up multiple teleportations to occur in sequence."] = "指定一个传送目的地，等待一段时间，该时间由距离和你的移动速度决定。传送发生时，对玩家原本所在位置和传送目的地周围同时施加闪电伤害。重复释放会按照顺序反复进行传送。",
