	["Weeping Wounds"] = "泣血创伤",
	["Weight Advantage"] = "千斤坠",
	["Weight of Despair"] = "绝望之地",
	["Weighted Sum searches will always sort using descending weighted sum\nAdditional post filtering options can be done these include:\nHighest Stat Value - Sort from highest to lowest Stat Value change of equipping item\nHighest Stat Value / Price - Sorts from highest to lowest by estimated Stat Value per currency\nLowest Price - Sorts from lowest to highest price of retrieved items\nHighest Weight - Displays the order retrieved from trade"] = "加权总分搜索始终按加权总分降序排列。\n还可对结果进行以下后续排序：\n最高属性评分：按装备物品带来的属性评分变化，从高到低排列。\n最高属性评分／价格：按每单位通货对应的预计属性评分，从高到低排列。\n最低价格：按搜索到的物品价格，从低到高排列。\n最高权重：保留交易网站返回的顺序。",
	["What need have I for defence when my enemies"] = "当我的敌人已化为灰烬与碎骨时",
	["When Channelling Empowered Spells ends, this Skill Triggers again for every\ntime it was Triggered while Channelling"] = "引导强化法术结束时，此技能按其引导期间已触发次数再次触发",
	["When bound by faith\n and respect, the flock\n will overwhelm the wolf."] = "以忠诚和尊敬连接，\n连狼群也被制伏的团结。",
	["When enabled, the mana spent by Arcane Cloak used at full mana"] = "启用后，满魔力时使用奥术斗篷消耗的魔力",
	["When enabled, the mana spent by Arcane Cloak used at full mana \nwill be added to the value provided in # of Mana spent Recently."] = "启用后，满魔力时使用奥术斗篷消耗的魔力\n会加至“近期内消耗的魔力”所填数值。",
	["When hit, release a nova of fiery vengeance, dealing spell fire damage and blinding enemies struck."] = "被击中时，释放炽焰复仇新星，对被击中的敌人造成火焰伤害并使其致盲。",
	["When hit, release a nova of venomous bile that deals spell chaos damage. This nova poisons and hinders on hit."] = "当你被击中时，释放毒液胆汁新星，造成法术混沌伤害。该新星在命中时会使敌人中毒并造成缓速。",
	["When used at range, throws out a chain, pulling you to the enemy hit dealing damage in an area behind them. When close to the enemy, just causes the area damage directly. Requires a One Handed Mace, Sceptre, Sword or Axe."] = "远程使用时，会投掷一条锁链，将你拉近被击中的敌人，并对它们身后一片区域内造成伤害。如果贴近敌人使用，则只会直接造成范围伤害。限定单手锤、短杖、剑类或斧类。",
	["When winning is all that matters, you'll use everything at your disposal."] = "当胜利成为唯一的指望，你就会放手一搏。",
	["When you Hit an Enemy with an Arrow from a Supported Skill, Summon a Mirage Archer which uses that Skill"] = "当你用被辅助技能发射的箭矢击中敌人时，召唤 1 个会使用此技能的幻影弓手",
	["When you Hit an Enemy with an Arrow from a Supported Skill, Summon a Mirage Archer which uses that Skill\nMirage Archer can use Triggered Attacks as though they were not Triggered"] = "当你用被辅助技能发射的箭矢击中敌人时，召唤 1 个会使用此技能的幻影弓手\n幻影弓手可以使用触发攻击，并视作没有触发",
	["When you Warcry, you and nearby Allies gain Onslaught for 4 seconds"] = "你使用战吼时， 你和周围友军在 4 秒内获得猛攻",
	["When you attack with The Saviour and deal a critical strike, this skill can summon a Mirage Saviour. Summoned Mirage Saviours will fight for you using whichever of your attack skills you dealt the critical strike with that caused them to be summoned. Mirage Saviours will not be resummoned using the same skills if you already have the maximum number of them."] = "使用救世者攻击并造成暴击时，该技能会召唤一个蜃影救世者。召唤的蜃影救世者会使用你在造成暴击时施展的技能。一旦达到他们的召唤上限，你就无法用相同的技能再次召唤他们。",
	["When you kill a Poisoned Enemy during any Flask Effect, Enemies within 1.5 metres are Poisoned"] = "在任意药剂生效期间击杀中毒的敌人时，1.5 米内的敌人陷入中毒",
	["When you leave your Banner's Area, recover 30% of the Valour consumed for that Banner"] = "当你离开自己的旗帜范围时，恢复该旗帜消耗胆魄的 30%",
	["When you take a Savage Hit, lose Baryatic Tension to recover that much Life, up to maximum"] = "承受残暴打击时，失去重压张力并回复等量的生命，最高不超过最大值",
	["When your Hits Impale Enemies, also Impale other Enemies near them\nInflict 5 additional Impales on Enemies you Impale\nFor 5 seconds after you Impale Enemies, they cannot be Impaled again, and Impales cannot be Called from them"] = "你击中穿刺的敌人时，也穿刺他周围的其它敌人\n对你穿刺的敌人施加 5 次额外穿刺\n你穿刺敌人后 5 秒内不能对它重复穿刺，并且这些穿刺无法被呼唤",
	["When your Traps Trigger, your nearby Traps also Trigger"] = "当你的陷阱触发时，你周围的陷阱也跟着触发",
	["Where you step, the sky darkens."] = "所行之处，天色为之暗淡。",
	["While active, grants the Avian's Might and Avian's Flight buffs in sequence. Avian's Might grants you and your minions a chance to deal Double Damage with hits for a duration. Avian's Flight grants you and your minions increased Movement Speed for a secondary duration."] = "当生效时，依次轮流赋予玩家鸟之力量和鸟之斗魄。鸟之力量会让你和你的召唤生物被击中后短时间内有一定几率造成双倍伤害。鸟之斗魄会让你和你的召唤生物移动速度增加。",
	["While active, grants the Cat's Stealth and Cat's Agility buffs in sequence. Cat's Stealth increases your critical strike chance, makes you harder to see, and gives you a chance to avoid damage for a short duration. Cat's Agility increases your attack and cast speed for a longer secondary duration."] = "当生效时，依次轮流赋予玩家猫之隐匿和猫之敏捷。猫之隐匿会提高暴击率，短时间内有一定几率避免伤害，并使你更难被敌人发现。猫之敏捷会在一段时间内增加你的攻击和施法速度。",
	["While active, periodically adds Crab Barriers to you, and grants additional Physical Damage reduction for each Crab Barrier you have. All Crab Barriers are lost when you take physical damage from a hit."] = "当生效时，每隔一段时间获得深海屏障，每个深海屏障使你获得额外物理伤害减免。所有的深海屏障会在你受到物理伤害时失去。",
	["While active, periodically applies a Spider's Web debuff to nearby Enemies, and Hinders them. Each Spider's Web on an Enemy increases the Damage they take. Hinder reduces their movement speed."] = "当生效时，每隔一段时间对周围敌人施加蜘蛛网减益效果，并减缓他们的移动速度。每层敌人身上的蜘蛛网会增加他们受到的伤害。",
	["While active, this skill inflicts the Weeping Black debuff on impaled enemies you hit with bow attacks. Weeping Black deals physical damage over time, and can stack up to five times. This skill cannot be cast by Totems."] = "在激活状态下，此技能使你用弓类攻击击中穿刺的敌人时施加漆黑鸣泣减益效果。漆黑鸣泣造成持续物理伤害，最多可叠加至 5 层。此技能无法由图腾施放。",
	["While active, your bow attacks inflict Cinderflame. Cinderflame deals fire damage over time, and can stack up to ten times. This skill cannot be cast by Totems."] = "在激活状态下，你的弓类攻击施加灰烬余火。灰烬余火造成持续火焰伤害，最多可叠加至 10 层。此技能无法由图腾施放。",
	["While affected by Glorious Madness, inflict Mania on nearby Enemies every second"] = "受疯狂荣光影响时，每秒对周围敌人施加狂热",
	["While ensnared, enemies take increased Projectile Damage from Attack Hits"] = "被诱捕的敌人承受的攻击击中投射物伤害提高",
	["While ensnared, enemies take increased Projectile Damage from Attack Hits\nEnsnared enemies always count as moving, and have less movement speed while trying to break the snare."] = "被诱捕的敌人承受的攻击击中投射物伤害提高\n被诱捕的敌人始终视为正在移动，尝试挣脱诱捕时移动速度总降。",
	["While the mind endures, so too will the body."] = "当心灵升华至永久不灭时, 肉体也将随之永存.",
	["While this skill is active, supported spells will be repeatedly triggered."] = "该技能激活时，被辅助的法术会反复触发。",
	["While you channel this skill, it releases pulses of electrical energy, dealing lightning damage in a growing semicircular area in front of you."] = "汇聚雷霆之力并从手中快速释放多次闪电，对你面前弧状区域内的所有敌人造成伤害，并逐渐扩大范围。",
	["While you channel this skill, it releases pulses of electrical energy, dealing lightning damage in a semicircular area in front of you."] = "汇聚雷霆之力并从手中快速释放多次闪电，对你面前弧状区域内的所有敌人造成伤害。",
	["While you have Disgorge Supported Spells fire Projectiles in a circle"] = "拥有喷吐时，被辅助法术会向四周发射投射物",
	["While you have at least 3 Ghastly Eye Jewels socketed:"] = "当你插上至少 3 颗苍白之凝珠宝时：",
	["While you have at least 3 Hypnotic Eye Jewels socketed:"] = "当你插上至少 3 颗安睡之凝珠宝时：",
	["While you have at least 3 Murderous Eye Jewels socketed:"] = "当你插上至少 3 颗凶残之凝珠宝时：",
	["While you have at least 3 Searching Eye Jewels socketed:"] = "当你插上至少 3 颗锐利之凝珠宝时：",
	["While you have no placed Banner, you can gain Valour"] = "未放置旗帜时，你可以获得胆魄",
	["While you run, this skill creates a small explosion with each step, dealing fire damage in an area around you."] = "该技能在你奔跑时每一步产生小规模爆炸，对周围造成火焰伤害。",
	["While you walk, this skill causes corpses near your steps to explode, dealing fire damage in an area. The explosions of the corpses are not affected by modifiers to spell damage, and cannot be reflected."] = "在你移动时，该技能会引爆周围的灵柩，造成火焰范围伤害。灵柩的爆炸无法被法术伤害词缀加成，并且该伤害无法被反射。",
	["Whirling Barrier"] = "杖影屏障",
