	["Yes"] = "是",
	["You Fell For It Fool"] = "你上当了，笨蛋",
	["You and Allies near your Banner Regenerate 0.1% of Life per second for each Valour consumed for that Banner"] = "旗帜每消耗一点胆魄，你和旗帜周围的友军每秒再生 0.1% 的生命",
	["You and Nearby Allies cannot gain Vaal Souls"] = "你与周围友军无法获得瓦尔之灵",
	["You and nearby Allies Regenerate 1.00% of Life per second"] = "你和周围友军每秒再生 1.00% 生命",
	["You and nearby Allies deal 30% increased Damage"] = "你和周围友军的伤害提高 30%",
	["You and nearby Allies deal 6 to 12 added Physical Damage for\neach Impale on Enemy"] = "敌人身上每有一个穿刺效果，你和周围友军的攻击便额外造成 6 - 12 附加物理伤害",
	["You and nearby Allies have +30% to Elemental Resistances"] = "你和周围友军的元素抗性 +30%",
	["You and nearby Allies have Tailwind"] = "你和周围友军具有提速尾流效果",
	["You and nearby allies are Immune to Chill"] = "你和周围友军免疫冰缓",
	["You and nearby allies are Immune to Curses"] = "你和周围友军免疫诅咒",
	["You and nearby allies are Immune to Freeze"] = "你和周围友军免疫冻结",
	["You and nearby allies are Immune to Ignite"] = "你和周围友军免疫点燃",
	["You and nearby allies are Immune to Shock"] = "你和周围友军免疫感电",
	["You and nearby allies are Immune to all Elemental Ailments"] = "你和周围友军免疫所有元素异常状态",
	["You and your Totems Regenerate 1% of Life per second for each Summoned Totem"] = "每个召唤的图腾使你和你的图腾每秒再生 1% 生命",
	["You and your pack run wild\nand free, brawling\nas you see fit."] = "你与族群恣意驰骋，\n随心所向，\n战意昂扬。",
	["You are Unaffected by Bleeding while Leeching"] = "偷取时不受流血影响",
	["You are not a vanishing spark, but a patient ember waiting to seed a great fire."] = "别成为等待消逝的余烬, 化为耐心等待熊熊燃烧的火苗.",
	["You are the heart of the empire, shining bright so that all are lifted up by your light."] = "你是帝国之心，给所有人带来光明。",
	["You can Cast 2 additional Brands"] = "可以施放 2 个额外烙印",
	["You can apply an additional Curse"] = "你能施加一个额外诅咒",
	["You can apply up to 50 Shocks to each Enemy"] = "你可以对每个敌人施加最多 50 次感电",
	["You can change this to see various buff values"] = "可修改此值以查看不同的增益数值",
	["You can click to select a row so that search begins from there."] = "点击选择一行，搜索将从该行开始。",
	["You can feel the fungus growing in your skull,"] = "你感觉到真菌在脑袋里增殖和成长，",
	["You can have an additional Tincture active"] = "你可以额外激活一种酊剂",
	["You can have up to 6 Steel Wards, and each grants +8% chance to Block Projectile Attack Damage."] = "最多拥有 6 层钢刃结界，每层提供 +8% 投射物攻击伤害格挡几率。",
	["You can hire a Mercenary permanently"] = "你可以永久雇佣一名佣兵",
	["You can inflict +1 Hallowing Flame on Enemies"] = "你可以对敌人施加 +1 层崇敬烈焰",
	["You can inflict Bleeding on an Enemy up to 8 times\nYour Bleeding does not deal extra Damage while the Enemy is moving and cannot be Aggravated\n50% less Damage with Bleeding"] = "你可以对一个敌人施加最多 8 层流血\n你的流血不会因敌人移动而造成额外伤害，且不能被加剧\n流血伤害总降 50%",
	["You can inflict an additional Ignite on each Enemy\nBase Ignite Duration is 1 second\n25% less Damage with Ignite\nCannot deal non-Fire Damage"] = "你可以对每个敌人额外施加一层点燃\n基础点燃持续时间为 1 秒\n点燃伤害总降 25%\n无法造成非火焰伤害",
	["You can inflict an additional Scorch on each Enemy"] = "你可以对敌人额外施加一层烧灼",
	["You can only have one Aura on you from your Blessing Skills"] = "你身上只能有一种祝福技能光环",
	["You can only have one Herald\n50% more Effect of Herald Buffs on you\n100% more Damage with Hits from Herald Skills\n50% more Damage Over Time with Herald Skills\nMinions from Herald Skills deal 25% more Damage\nYour Aura Skills are Disabled"] = "你只能有一种捷效果\n你身上的捷增益总效果总增 50%\n捷技能的总击中伤害总增 100%\n捷技能的总持续伤害总增 50%\n捷技能召唤生物的伤害总增 25%\n你禁用光环技能",
	["You can't deal Chaos damage"] = "你无法造成混沌伤害",
	["You can't deal Cold damage"] = "你无法造成冰霜伤害",
	["You can't deal Damage with Skills yourself\n+1 to maximum number of Summoned Totems"] = "你自己发动的技能无法造成伤害\n召唤图腾数量上限 +1",
	["You can't deal Fire damage"] = "你无法造成火焰伤害",
	["You can't deal Lightning damage"] = "你无法造成闪电伤害",
	["You can't deal Physical damage"] = "你无法造成物理伤害",
	["You cannot Cast Supported Curse Spells"] = "你不能施放被辅助的诅咒法术",
	["You cannot add support gems to this group, but support gems in"] = "无法向此技能组添加辅助宝石，但其他技能组中插在同一物品上的辅助宝石",
	["You cannot be Frozen if you've been Frozen Recently"] = "你被冰冻后的近期内免疫冰冻",
	["You cannot be Hindered"] = "你无法被缓速",
	["You cannot be Ignited if you've been Ignited Recently"] = "若你近期内被点燃，则你不会再被点燃",
	["You cannot be Impaled"] = "你不能被穿刺",
	["You cannot be Maimed"] = "你无法被瘫痪",
	["You cannot be Shocked if you've been Shocked Recently"] = "若你近期内受到感电效果，则你不会再受到感电",
	["You cannot delete this group, but it will disappear if you un-allocate the node."] = "无法删除此技能组；取消分配提供此技能的天赋后，技能组会自动消失。",
	["You cannot delete this group, but it will disappear if you un-equip the item."] = "无法删除此技能组；卸下提供此技能的物品后，技能组会自动消失。",
	["You cannot use this Skill yourself, Shaper Memory will use it for you"] = "你无法亲自使用此技能，塑界者的记忆会代你使用",
	["You cannot use this Skill yourself, your Statues will use this Skill for you"] = "你无法施放该技能，雕像会为你施放该技能",
	["You count as Dual Wielding while you are Unencumbered\n40% more Attack Speed with Melee Skills while you are Unencumbered\nAdds 14 to 20 Attack Physical Damage to Melee Skills per 10 Dexterity while you are Unencumbered"] = "你在无负重状态下视为双持武器\n你在无负重状态下近战技能的攻击速度总增 40%\n你在无负重状态下每 10 点敏捷都使近战技能附加 14 到 20 点物理攻击伤害",
	["You count as on Full Life while at 90% of maximum Life or above"] = "达到或高于生命上限的 90% 时将你视作满血",
	["You count as on Low Life while at 55% of maximum Life or below"] = "达到或低于生命上限的 55% 时将你视作濒血",
	["You die if Linked target dies"] = "羁绊对象战败则你也战败",
	["You gain Added Cold Damage instead of Added Damage of other types if Dexterity exceeds both other Attributes"] = "如果敏捷高于其他两项属性，你获得的附加其他类型伤害将转为获得附加冰霜伤害",
	["You gain Added Lightning Damage instead of Added Damage of other types if Intelligence exceeds both other Attributes"] = "如果智力高于其他两项属性，你获得的附加其他类型伤害将转为获得附加闪电伤害",
	["You gain Onslaught for 20 seconds on using a Vaal Skill"] = "使用瓦尔技能时，获得猛攻状态，持续 20 秒",
	["You have 1% less damage taken from hits per stack of fortification:"] = "每层护体使你承受的击中伤害总降 1%：",
	["You have 1% less damage taken from hits per stack of fortification:\nHas a default cap of 20 stacks."] = "每层护体使你承受的击中伤害总降 1%：\n默认上限为 20 层。",
	["You have Consecrated Ground around you while stationary"] = "站定时，脚下产生奉献地面",
	["You have Culling Strike against Cursed Enemies"] = "你可以终结被诅咒的敌人",
	["You have Everlasting Sacrifice if at least 6 Corrupted Items are Equipped"] = "若至少装备了 6 件腐化物品，你将拥有永恒献祭",
	["You have Impenetrable Shrine Buff while affected by no Flasks"] = "当没有任何药剂效果时，获得无畏神龛增益效果",
	["You have Onslaught if you've Summoned a Totem Recently"] = "若你近期内召唤过图腾，则你获得猛攻",
	["You have Onslaught if you've changed Stance Recently"] = "若你最近改变过姿态，获得猛攻",
	["You have Phasing if you have Suppressed Spell Damage Recently"] = "若你近期压制过法术伤害，则获得迷踪效果",
	["You have Sacrifice of Blood if at least 8 Corrupted Items are Equipped"] = "若至少装备了 8 件腐化物品，你将拥有鲜血祭品",
	["You have Shepherd of Souls if at least 4 Corrupted Items are Equipped"] = "若至少装备了 4 件腐化物品，你将拥有灵魂牧者",
	["You have the Blue Flag"] = "蓝旗背负者",
	["You have the Green Flag"] = "绿旗背负者",
	["You have the Karui Spirit"] = "背负卡鲁之灵",
	["You have the Red Flag"] = "红旗背负者",
	["You have your maximum Fortification"] = "你具有最大护体层数",
	["You lose 10 Rage every second if you have not been Hit or gained Rage in the last 2 seconds."] = "若过去 2 秒内未被击中且未获得怒火，则每秒失去 10 点怒火。",
	["You lose Rampage if you do not get a Kill within 5 seconds."] = "若 5 秒内未击败敌人，则失去暴走。",
	["You must gain Valour from melee combat to use this skill, which will consume all Valour to place a banner with an aura. The aura will be larger and more powerful the more Valour was consumed. The banner lasts for a duration, but will end early if you leave the aura, or use the skill again while it's active."] = "必须在近战战斗中积累胆魄才能使用该技能，消耗所有胆魄，放置一面具有光环的旗帜。消耗的胆魄越多，光环的范围越大、效果越强。旗帜持续一段时间，当你离开光环范围，或在激活期间再次使用该技能，旗帜就会提前结束。",
	["You must log in to use the search feature"] = "请登录后使用搜索功能",
	["You take 20% reduced Extra Damage from Critical Strikes"] = "受到的暴击伤害降低 20%",
	["You take 30% reduced Extra Damage from Critical Strikes"] = "受到的暴击伤害降低 30%",
	["You take 40% reduced Extra Damage from Critical Strikes by Cursed Enemies"] = "受诅咒的敌人的暴击对你造成的额外伤害降低 40%",
	["You take no Extra Damage from Critical Strikes while Elusive"] = "灵巧效果下，不会受到暴击造成的额外伤害",
	["You will automatically be considered to be Channeling if your main skill is a channelled skill,"] = "主技能为引导技能时，自动视为正在引导，",
	["You will automatically be considered to be Channeling if your main skill is a channelled skill,\nbut you can use this option to force it if necessary."] = "主技能为引导技能时，自动视为正在引导，\n必要时可使用此选项强制启用该条件。",
	["You will automatically be considered to be Leeching if you have 'Life Leech effects are not removed at Full Life',"] = "拥有“生命偷取效果不会在满血时移除”时，自动视为正在偷取，",
	["You will automatically be considered to be Leeching if you have 'Life Leech effects are not removed at Full Life',\nbut you can use this option to force it if necessary."] = "拥有“生命偷取效果不会在满血时移除”时，自动视为正在偷取，\n必要时可使用此选项强制启用该条件。",
	["You will automatically be considered to be on Low Energy Shield if you have at least 50% ES reserved,"] = "至少保留 50% 能量护盾时，自动视为处于低能量护盾状态，",
	["You will automatically be considered to be on Low Energy Shield if you have at least 50% ES reserved,\nbut you can use this option to force it if necessary."] = "至少保留 50% 能量护盾时，自动视为处于低能量护盾状态，\n必要时可使用此选项强制启用该条件。",
	["You will automatically be considered to be on Low Mana if you have at least 50% mana reserved,"] = "至少保留 50% 魔力时，自动视为处于低魔状态，",
	["You will automatically be considered to be on Low Mana if you have at least 50% mana reserved,\nbut you can use this option to force it if necessary."] = "至少保留 50% 魔力时，自动视为处于低魔状态，\n必要时可使用此选项强制启用该条件。",
	["You will automatically be considered to have Attacked Recently if your main skill is an attack,"] = "主技能为攻击时，自动视为近期内进行过攻击，",
	["You will automatically be considered to have Cast a Spell Recently if your main skill is a spell,"] = "主技能为法术时，自动视为近期内施放过法术，",
	["You will automatically be considered to have Hit Recently if your main skill Hits and is self-cast,"] = "主技能自行施放且造成击中时，自动视为近期内造成过击中，",
	["You will automatically be considered to have Hit Recently if your main skill Hits and is self-cast,\nbut you can use this option to force it if necessary."] = "主技能自行施放且造成击中时，自动视为近期内造成过击中，\n必要时可使用此选项强制启用该条件。",
	["You will automatically be considered to have Summoned a Totem Recently if your main skill is a Totem,"] = "主技能为图腾时，自动视为近期内召唤过图腾，",
	["You will automatically be considered to have Summoned a Totem Recently if your main skill is a Totem,\nbut you can use this option to force it if necessary."] = "主技能为图腾时，自动视为近期内召唤过图腾，\n必要时可使用此选项强制启用该条件。",
	["You will automatically be considered to have a Totem if your main skill is a Totem,"] = "主技能为图腾时，自动视为拥有图腾，",
	["You will automatically be considered to have a Totem if your main skill is a Totem,\nbut you can use this option to force it if necessary."] = "主技能为图腾时，自动视为拥有图腾，\n必要时可使用此选项强制启用该条件。",
	["You will automatically be considered to have unbroken Ward if you have Olroth's Resolve active or"] = "启用欧罗什的决心，或满足下述条件时，自动视为结界未破：",
	["You will automatically be considered to have unbroken Ward if you have Olroth's Resolve active or\nan Iron Flask with enough Flask Charges gained on Ward Break."] = "启用欧罗什的决心，或满足下述条件时，自动视为结界未破：\n使用坚铁药剂，并在结界破裂时获得足够的药剂充能。",
	["You will automatically be considered to have used a Minion skill Recently if your main skill is a Minion skill,"] = "主技能为召唤生物技能时，自动视为近期内使用过召唤生物技能，",
	["You will automatically be considered to have used a Movement skill Recently if your main skill is a movement skill,"] = "主技能为位移技能时，自动视为近期内使用过位移技能，",
	["You will automatically be considered to have used a Vaal skill Recently if your main skill is a Vaal skill,"] = "主技能为瓦尔技能时，自动视为近期内使用过瓦尔技能，",
	["You're the crazy one!"] = "你才疯了！",
	["Your Absolution Skill Damage will not be scaled with Count setting."] = "赦罪技能自身的伤害不随数量设置缩放。",
	["Your Absolution Skill Damage will not be scaled with Count setting.\nBy default it multiplies both minion count and skill hit count which leads to incorrect\nTotal DPS calculation since Absolution cannot inherently shotgun.\nDo not enable if you use Spell Totem support, Spell Cascade support or similar supports"] = "赦罪技能自身的伤害不随数量设置缩放。\n默认同时乘以召唤生物数量和技能击中次数，可能导致\n总每秒伤害计算不准确，因为赦免本身无法使多个投射物重复命中同一目标。\n使用法术图腾、多重范围施法或类似辅助时请勿启用",
	["Your Action Speed is at least 90% of base value"] = "你的行动速度至少是基础值的90%",
	["Your Banner Buffs Linger on you for 3 seconds after you leave the Area"] = "离开效果范围后，你的旗帜增益在你身上持续 3 秒",
	["Your Chaos Damage can Freeze"] = "你的混乱伤害可以造成冰冻",
	["Your Chills can reduce Action Speed by up to a maximum of 40%"] = "你的冰缓效果可以降低行动速度，最多降低 40%",
	["Your Critical Strike Chance is Lucky"] = "幸运的暴击率",
	["Your Critical Strikes Knock Back Shocked Enemies"] = "暴击会击退被感电的敌人",
	["Your Critical Strikes have a 5% chance to deal Double Damage"] = "你的暴击有 5% 的几率伤害翻倍",
	["Your Curses have 20% increased Effect if 50% of Curse Duration expired"] = "若持续时间耗减了 50%，你的诅咒效果提高 20%",
	["Your Dominating Blow Skill Damage will not be scaled with Count setting."] = "霸气之击技能自身的伤害不随数量设置缩放。",
	["Your Dominating Blow Skill Damage will not be scaled with Count setting.\nBy default it multiplies both minion count and skill hit count which leads to incorrect\nTotal DPS calculation since Dominating Blow cannot inherently shotgun.\nDo not enable if you use Spell Totem support, Spell Cascade support or similar supports"] = "霸气之击技能自身的伤害不随数量设置缩放。\n默认同时乘以召唤生物数量和技能击中次数，可能导致\n总每秒伤害计算不准确，因为霸气之击本身无法使多个投射物重复命中同一目标。\n使用法术图腾、多重范围施法或类似辅助时请勿启用",
	["Your Elemental Resistances cannot be lowered by Curses"] = "你的元素抗性无法被诅咒降低",
	["Your Hexes can affect Hexproof Enemies"] = "你的魔蛊可以影响无咒的敌人",
	["Your Hexes have infinite Duration\n20% less Effect of your Curses"] = "你的魔蛊有无限的持续时间\n你的诅咒效果总降 20%",
	["Your Hits against Marked Enemy cannot be Blocked or Suppressed"] = "你对被标记敌人的击中无法被格挡或压制",
	["Your Hits always inflict Freeze, Shock and Ignite while Unbound"] = "不羁期间，你的击中始终造成冻结、感电和点燃",
	["Your Hits ignore Enemy Monster Cold Resistances if all Equipped Rings are Cryonic Rings"] = "若所有已装备的戒指都是冰凝戒指，你的击中会无视敌人的冰霜抗性",
	["Your Hits ignore Enemy Monster Lightning Resistances if all Equipped Rings are Synaptic Rings"] = "若所有已装备的戒指都是突触戒指，你的击中会无视敌人的闪电抗性",
	["Your Hits permanently Intimidate Enemies that are on Full Life"] = "击中满血敌人时，将使他们永久受到威吓",
	["Your Holy Strike Skill Damage will not be scaled with Count setting."] = "神圣打击技能自身的伤害不随数量设置缩放。",
	["Your Holy Strike Skill Damage will not be scaled with Count setting.\nBy default it multiplies both minion count and skill hit count which leads to incorrect\nTotal DPS calculation since Holy Strike cannot inherently shotgun."] = "神圣打击技能自身的伤害不随数量设置缩放。\n默认同时乘以召唤生物数量和技能击中次数，可能导致\n总每秒伤害计算不准确，因为神圣打击本身无法使多个投射物重复命中同一目标。",
	["Your Mark Transfers to another Enemy when Marked Enemy dies"] = "被标记的敌人被击败后，你的印记转移给另一个敌人",
	["Your Maximum Endurance Charges is equal to your Maximum Frenzy Charges"] = "你的耐力球数量上限等于你的狂怒球数量上限",
	["Your Mercenary Taunts on Hit"] = "你的佣兵击中时嘲讽",
	["Your Mercenary and their Minions deal 15% increased Damage"] = "你的佣兵及其召唤生物造成的伤害提高 15%",
	["Your Mercenary and their Minions deal 8% more Damage for\neach Unique item they have equipped"] = "你的佣兵及其召唤生物每装备一件传奇物品，造成的伤害总增 8%",
	["Your Mercenary and their Minions have 15% increased maximum Life"] = "你的佣兵及其召唤生物的最大生命提高 15%",
	["Your Mercenary can equip Unique Amulets"] = "你的佣兵可以装备传奇护身符",
	["Your Mercenary can equip Unique Belts"] = "你的佣兵可以装备传奇腰带",
	["Your Mercenary can equip Unique Boots"] = "你的佣兵可以装备传奇鞋子",
	["Your Mercenary can equip Unique Gloves"] = "你的佣兵可以装备传奇手套",
	["Your Mercenary can equip Unique Helmets"] = "你的佣兵可以装备传奇头盔",
	["Your Mercenary can equip Unique Rings"] = "你的佣兵可以装备传奇戒指",
	["Your Mercenary can equip Unique Weapons, Shields and Quivers"] = "你的佣兵可以装备传奇武器、盾与箭袋",
	["Your Mercenary has 50% increased effect of Non-Curse Auras from Skills"] = "你的佣兵来自技能的非诅咒光环效果提高 50%",
	["Your Movement Speed is equal to the highest Movement Speed among Linked Players"] = "你的移动速度与羁绊玩家中的移动速度最高者相同",
	["Your Non-Blessing Skills which Reserve Mana are Disabled while you have an Aura from a Supported Skill on you"] = "你保留魔力的非祝福技能在你身上有辅助技能的光环时被禁用",
	["Your Offering Skills also affect you"] = "你的奉献技能会同时影响你",
	["Your Offering Skills do not require a Corpse"] = "你的奉献技能不需要灵柩",
	["Your Offerings have 50% reduced Effect on you"] = "你的奉献技能对自身的效果降低 50%",
	["Your Warcries attempt to shake extra items from Corpses"] = "你的战吼会尝试从灵柩中震出额外物品",
	["Your Warcries do not grant Buffs or Charges to You\n100% more Warcry Duration"] = "你的战吼不为你提供增益或能量球\n战吼持续时间总增 100%",
	["Your Warcries inflict Hallowing Flame"] = "你的战吼施加崇敬烈焰",
	["Your Warcries open Chests"] = "你的战吼能打开箱子",
	["Your and nearby allies' Energy Shield Recharges are not delayed by Damage"] = "你与周围友军不会因为承受伤害而延迟能量护盾回复的间隔时间",
	["Your and nearby allies' Skills Cost no Mana"] = "你与周围友军施放技能时不消耗魔力",
	["Your enemies will know your agony tenfold."] = "你的敌人将会受到十倍的奉还。",
	["Your entire existence is merely\na jest to entertain Chaos."] = "你的全部存在不过是\n供混沌取乐的戏言。",
	["Your foes will beg not for their pitiful lives, but for a quick, merciful death."] = "你的对手不会求你饶命, 只会求你给他们个痛快.",
	["Your hits can't be Evaded\nNever deal Critical Strikes"] = "你的击中无法被闪避\n无法造成暴击",
	["Your melee weapon strikes enemies, converting physical damage to a random element. Then, depending on the element chosen, it releases a fiery explosion, an arcing bolt of lightning, or an icy wave. It will avoid choosing the same element twice in a row."] = "使用近战武器打击敌人，将物理伤害转换为随机的元素伤害。根据转换成的元素释放出猛烈的爆炸、弧动的闪电箭或冰霜波。不会连续两次选择相同的元素。",
	["Your shield shatters, dealing physical spell damage to enemies in an area, based on the shield's quality. For a short duration after this, you will be unable to block and will gain no defences from your shield, but your spells will deal added physical damage."] = "盾牌破碎，根据盾牌品质，对一片区域内的敌人造成物理法术伤害。之后短时间内你都不能格挡，也不能从盾牌中得到防御值，但你的法术附加物理伤害。",
	["Your ward shatters, dealing physical spell damage to enemies in an area, based on the amount of ward you have. Enemies hit are inflicted with Enervation, a Debuff that lowers Movement Speed by 20% and prevents Life and Energy Shield Recovery for 4 seconds."] = "你的结界猛然破碎，基于当前结界值对范围内敌人造成物理法术伤害。被击中的敌人将陷入衰退状态，移动速度降低20%，并在4秒内无法恢复生命值与能量护盾。",
	["Yours is a legacy of\nheroes... fallen, or\notherwise."] = "你所继承的是英雄的\n血脉……无论他们最终\n陨落，抑或幸存",
